def _percent_encode_opaque_preserving_percent(s):
    # Opaque path strings already may contain %XX sequences from input; encode required chars but keep % as-is
    out = []
    for ch in s:
        o = ord(ch)
        if o <= 0x1F or o > 0x7E or ch in OPAQUE_PATH_ENCODE_SET:
            if ch == '%' :
                out.append(ch)
            else:
                for b in ch.encode('utf-8'):
                    out.append("%{:02X}".format(b))
        else:
            out.append(ch)
    return "".join(out)

def _encode_path_segment(seg):
    # Segments are stored already partially encoded? We store raw segments (with existing % sequences preserved as raw '%')
    # Encode chars in PATH_ENCODE_SET and non-ascii/C0, preserving % (do not encode % itself as it's not in set)
    out = []
    for ch in seg:
        o = ord(ch)
        if o <= 0x1F or o > 0x7E or ch in PATH_ENCODE_SET:
            for b in ch.encode('utf-8'):
                out.append("%{:02X}".format(b))
        else:
            out.append(ch)
    return "".join(out)

def _encode_query(q, special):
    es = QUERY_ENCODE_SET_SPECIAL if special else QUERY_ENCODE_SET
    out = []
    for ch in q:
        o = ord(ch)
        # Rust url query encode set: C0, space, ", #, <, > and for special also '
        if o <= 0x1F or o > 0x7E or ch in es or (special and ch == "'"):
            for b in ch.encode('utf-8'):
                out.append("%{:02X}".format(b))
        else:
            out.append(ch)
    return "".join(out)

def _encode_fragment(f):
    out = []
    for ch in f:
        o = ord(ch)
        if o <= 0x1F or o > 0x7E or ch in FRAGMENT_ENCODE_SET:
            if ch == ' ':
                out.append("%20")
            else:
                for b in ch.encode('utf-8'):
                    out.append("%{:02X}".format(b))
        else:
            out.append(ch)
    return "".join(out)

