# --- Host parsing ---
def _parse_ipv4_number(part):
    if part == "":
        return None
    radix = 10
    s = part
    if len(s) >= 2 and s[:2].lower() == "0x":
        radix = 16; s = s[2:]
        if s == "":
            return 0
    elif len(s) >= 2 and s[0] == "0":
        radix = 8; s = s[1:]
        if s == "":
            return 0
    try:
        # only valid digits for radix
        if radix == 10:
            if not s.isdigit(): return None
        elif radix == 16:
            int(s, 16)
        else:
            int(s, 8)
        return int(s, radix)
    except Exception:
        return None

def _parse_ipv4(host):
    # Returns serialized ipv4 string or None if not ipv4-like; raises ValueError if ipv4-like but invalid
    parts = host.split(".")
    if parts and parts[-1] == "":
        parts = parts[:-1]
        if not parts:
            return None
    if not parts:
        return None
    nums = []
    is_ipv4_like = False
    for p in parts:
        # Determine if this part looks numeric
        n = _parse_ipv4_number(p)
        if n is None:
            return None
        nums.append(n)
        is_ipv4_like = True
    if not is_ipv4_like:
        return None
    if len(nums) > 4:
        raise ValueError("ipv4 too many parts")
    for n in nums[:-1]:
        if n > 255:
            raise ValueError("ipv4 overflow")
    last = nums[-1]
    if last >= 256 ** (5 - len(nums)):
        raise ValueError("ipv4 last overflow")
    addr = last
    for i, n in enumerate(nums[:-1]):
        addr += n * (256 ** (3 - i))
    # serialize
    return "%d.%d.%d.%d" % ((addr >> 24) & 0xff, (addr >> 16) & 0xff, (addr >> 8) & 0xff, addr & 0xff)

def _parse_ipv6(host_in):
    # host_in without brackets, return canonical serialization or raise ValueError
    s = host_in
    if s == "":
        raise ValueError("empty ipv6")
    # Use Python ipaddress for parsing/serialization but need WHATWG canonical (lowercase, compressed)
    import ipaddress
    try:
        ip = ipaddress.IPv6Address(s)
    except Exception as e:
        raise ValueError(str(e))
    return ip.compressed.lower()

def _domain_to_ascii(domain):
    # Percent-decode first, then IDNA (UTS46-ish using Python's idna codec per label)
    # Input domain is a string; bytes percent decoding as UTF-8.
    # Rust url uses idna crate; approximate.
    import urllib.parse as _up
    try:
        decoded = _up.unquote_to_bytes(domain).decode('utf-8', 'strict')
    except Exception:
        # If not valid UTF-8 after percent decode, fail?
        raise ValueError("domain utf8")
    if decoded == "":
        return ""
    # Forbidden host code points check will be done by caller
    # Split labels
    labels = decoded.split(".")
    out_labels = []
    for label in labels:
        if label == "":
            out_labels.append("")
            continue
        # Check if all ascii
        if all(ord(c) < 128 for c in label):
            out_labels.append(label.lower())
        else:
            try:
                # Python's 'idna' implements IDNA 2003; map ß etc differently but close
                ascii_label = label.encode('idna').decode('ascii')
            except Exception:
                # Try punycode manually
                try:
                    ascii_label = "xn--" + label.encode('punycode').decode('ascii')
                except Exception:
                    raise ValueError("idna")
            out_labels.append(ascii_label.lower())
    result = ".".join(out_labels)
    # Rust url also checks labels etc; ignore
    return result

_FORBIDDEN_HOST_CHARS = set('\x00\t\n\r #/:<>?@[\\]^|')
_FORBIDDEN_DOMAIN_CHARS = set('\x00\t\n\r #%:<>?@[\\]^|')

def _parse_host(host_str, is_special, is_file=False):
    # Returns (host_str_serialized, host_type) or raises ValueError
    if host_str == "":
        if is_special and not is_file:
            raise ValueError("empty host")
        return ("", 'empty')
    if host_str.startswith("["):
        if not host_str.endswith("]"):
            raise ValueError("ipv6 bracket")
        inner = host_str[1:-1]
        return (_parse_ipv6(inner), 'ipv6')
    if is_special:
        # domain
        # Check forbidden domain chars (after ?) spec checks in domain string
        # If any forbidden, failure
        for c in host_str:
            if c in _FORBIDDEN_DOMAIN_CHARS:
                raise ValueError("forbidden host char")
        # Ends in number check for ipv4
        # Try ipv4 parse if last part looks numeric etc.
        # WHATWG: if host ends in a number, treat as ipv4
        parts = host_str.split(".")
        last = parts[-1] if parts else ""
        if last == "" and len(parts) > 1:
            last = parts[-2]
        ends_in_number = False
        if last != "":
            if last.isdigit():
                ends_in_number = True
            elif _parse_ipv4_number(last) is not None and all(ch in "0123456789abcdefABCDEFxX." for ch in last):
                # hex like
                try:
                    if _parse_ipv4(last) is not None or True:
                        pass
                except Exception:
                    ends_in_number = True
                # simpler: if parsing ipv4_number returns not None
                if _parse_ipv4_number(last) is not None:
                    ends_in_number = True
        if ends_in_number:
            ipv4 = _parse_ipv4(host_str)  # may raise
            if ipv4 is None:
                raise ValueError("ipv4 parse fail")
            return (ipv4, 'ipv4')
        ascii_domain = _domain_to_ascii(host_str)
        if ascii_domain == "":
            raise ValueError("empty domain")
        return (ascii_domain, 'domain')
    else:
        # opaque host
        for c in host_str:
            if c in _FORBIDDEN_HOST_CHARS:
                raise ValueError("forbidden host")
        # percent encode C0 etc; Rust percent-encodes non-ascii? Opaque host encoding encodes bytes except certain.
        # Host is percent-encoded using C0 control encode set.
        encoded = _percent_encode(host_str, set())
        return (encoded, 'opaque')

def _is_windows_drive_letter(s):
    return len(s) == 2 and s[1] in ':|' and s[0].isalpha()

def _normalize_drive_letter(s):
