def _is_single_dot_segment(seg):
    return seg == "." or seg.lower() == "%2e"
def _is_double_dot_segment(seg):
    low = seg.lower()
    return seg == ".." or low == ".%2e" or low == "%2e." or low == "%2e%2e"

