def _parse_port(port_str, scheme):
    if port_str == "":
        return None
    if not port_str.isdigit():
        raise UrlParseError("port invalid")
    # leading zeros stripped by int
    try:
        p = int(port_str)
    except:
        raise UrlParseError("port")
    if p > 65535:
        raise UrlParseError("port overflow")
    if scheme in SPECIAL_SCHEMES and SPECIAL_SCHEMES[scheme] == p:
        return None
    # file scheme port not allowed
    if scheme == 'file':
        raise UrlParseError("file port")
    return p

def _split_authority(authority_and_rest):
    # authority ends at / ? # or (for special) backslash
    # Returns authority, rest starting with delimiter or ''
