    i = 0
    while i < len(authority_and_rest):
        if authority_and_rest[i] in '/?#':
            break
        i += 1
    return authority_and_rest[:i], authority_and_rest[i:]

def _parse_authority(authority, scheme, is_special):
    # returns username,password,host,host_type,port
    username = ""
    password = None
    hostport = authority
    if '@' in authority:
        # last @ separates userinfo
        userinfo, hostport = authority.rsplit('@', 1)
        if ':' in userinfo:
            username, password = userinfo.split(':', 1)
        else:
            username = userinfo
            password = None
        # percent encode handled at serialize time from raw userinfo; but need decode %? Rust keeps % sequences as is in username/password.
        # We'll store raw userinfo strings (they may contain %)
        # For serialization, our encoder should not re-encode % (percent not in encode set), so fine.
    host = hostport
