    # path_str for hierarchical: may be "", "/a/b", "a/b" (for relative handled outside)
    if path_str == "":
        return [""]
    if path_str.startswith("/"):
        segs = path_str.split("/")[1:]
    else:
        segs = path_str.split("/")
    # Resolve dot segments
    out = []
    # Spec path handling: last segment handling for dot segments (append empty)
    # We'll process segments including empties, applying:
    is_last_index = len(segs)-1
    for idx, seg in enumerate(segs):
        if _is_double_dot_segment(seg):
            if out:
                out.pop()
            if idx == is_last_index:
                out.append("")
        elif _is_single_dot_segment(seg):
            if idx == is_last_index:
                out.append("")
            # else skip
        else:
            out.append(_encode_seg(seg))
    if not out:
        out = [""]
    return out

