# ---------------- CSS selectors ----------------
class SelectorError(Exception):
    pass

def _is_name_start(c):
    return c.isalpha() or ord(c) >= 0x80 or c == '_'
def _is_name_char(c):
    return c.isalnum() or ord(c) >= 0x80 or c in '_-'

class CSSParser:
    def __init__(self, s):
        self.s = s
        self.i = 0
        self.n = len(s)
    def error(self):
        raise SelectorError("parse error")
    def peek(self, off=0):
        j = self.i + off
        return self.s[j] if j < self.n else ''
    def eof(self):
        return self.i >= self.n
    def skip_whitespace(self):
        # returns True if any whitespace/comments consumed
        had = False
        while self.i < self.n:
            c = self.s[self.i]
            if c in ' \t\n\r\f':
                had = True; self.i += 1
            elif c == '/' and self.i + 1 < self.n and self.s[self.i+1] == '*':
                end = self.s.find('*/', self.i+2)
                if end == -1:
                    self.i = self.n
                else:
                    self.i = end + 2
                had = True
            else:
                break
        return had
    def consume_escape(self):
        # self.s[self.i] == '\\'
        if self.i >= self.n:
            return '\ufffd'
        self.i += 1  # backslash
        if self.i >= self.n:
            return '\ufffd'
        c = self.s[self.i]
        if c in '0123456789abcdefABCDEF':
            j = self.i
            hexdigits = ''
            while j < self.n and len(hexdigits) < 6 and self.s[j] in '0123456789abcdefABCDEF':
                hexdigits += self.s[j]; j += 1
            # one whitespace after hex escape is consumed (CRLF counts as one)
            if j < self.n and self.s[j] in ' \t\n\r\f':
                if self.s[j] == '\r' and j+1 < self.n and self.s[j+1] == '\n':
                    j += 2
                else:
                    j += 1
            self.i = j
            try:
                cp = int(hexdigits, 16)
            except:
                return '\ufffd'
            if cp == 0 or cp > 0x10FFFF or 0xD800 <= cp <= 0xDFFF:
                return '\ufffd'
            return chr(cp)
        elif c in '\n\r\f':
            # escaped newline is invalid in ident; for our purposes treat as error marker
            # cssparser: consume_escape returns error; selectors parser will fail when parsing ident
            self.error()
        else:
            self.i += 1
            return c
    def parse_ident(self):
        # CSS identifier: [-]? (name-start | escape) (name-char | escape)*  or --...
        start = self.i
        # We implement consumption manually.
        if self.peek() == '-':
            # lookahead: need second char name-start, '-', or escape
            nxt = self.peek(1)
            if nxt == '-' or _is_name_start(nxt) or nxt == '\\':
                self.i += 1
            else:
                self.error()
        # now at first significant char
        c = self.peek()
        if c == '\\':
            out = [self.consume_escape()]
        elif _is_name_start(c):
            out = [c]; self.i += 1
        else:
            self.error()
        while self.i < self.n:
            c = self.s[self.i]
            if _is_name_char(c):
                out.append(c); self.i += 1
            elif c == '\\':
                # backslash newline -> break / error? spec ident ends before it and escape is invalid
                if self.i + 1 < self.n and self.s[self.i+1] in '\n\r\f':
                    self.error()
                out.append(self.consume_escape())
            else:
                break
        return "".join(out)
    def parse_name(self):
        # name sequence: (name-char | escape)+ ; used for hash etc? Not directly.
        out = []
        while self.i < self.n:
            c = self.s[self.i]
            if _is_name_char(c):
                out.append(c); self.i += 1
            elif c == '\\':
                out.append(self.consume_escape())
            else:
                break
        if not out:
            self.error()
        return "".join(out)
    def parse_string(self):
        quote = self.s[self.i]
        self.i += 1
        out = []
        while self.i < self.n:
            c = self.s[self.i]
            if c == quote:
                self.i += 1
                return "".join(out)
            if c in '\n\r\f':
                self.error()  # bad string
            if c == '\\':
                self.i += 1
                if self.i >= self.n:
                    break
                nxt = self.s[self.i]
                if nxt in '\n\r\f':
                    # line continuation
                    if nxt == '\r' and self.i+1 < self.n and self.s[self.i+1] == '\n':
                        self.i += 2
                    else:
                        self.i += 1
                    continue
                # escape char
                self.i -= 1
                out.append(self.consume_escape())
                continue
            out.append(c); self.i += 1
        # EOF in string: cssparser yields string token at EOF (tolerated)
        return "".join(out)
    def parse_hash_id(self):
        # At '#': hash token must be a valid identifier (per selectors for ID)
        # Consume name chars/escapes after #, then validate that the token would be an identifier.
        # Determine raw characters forming the name.
        assert self.peek() == '#'
        self.i += 1
        # Need to check identifier validity of following sequence.
        # Save position; try parse_ident-like validation but hash may start with digit -> invalid for ID selector.
        # If following is ident start sequence, parse it.
        # Approach: try to determine if the sequence starting here forms an ident.
        # CSS Syntax: hash is an ID if it follows identifier rules.
        # We'll attempt: peek ident parsing on a substring.
        save = self.i
        try:
            val = self.parse_ident()
            return val
        except SelectorError:
            self.error()
    # -------- selector parsing --------
    def parse_selector_list(self):
        selectors = []
        self.skip_whitespace()
        if self.eof():
            self.error()
        while True:
            sel = self.parse_complex_selector()
            selectors.append(sel)
            self.skip_whitespace()
            if self.eof():
                break
            if self.peek() == ',':
                self.i += 1
                self.skip_whitespace()
                if self.eof():
                    self.error()
                continue
            else:
                self.error()
        return selectors
    def parse_complex_selector(self):
        # returns list of (combinator_to_left, compound) ; first combinator None
        parts = []
        combinator = None
        while True:
            had_ws = self.skip_whitespace()
            if self.eof() or self.peek() == ',':
                if not parts:
                    self.error()
                break
            c = self.peek()
            if c in '>+~':
                if not parts:
                    self.error()
                combinator = c
                self.i += 1
                # after combinator, a compound must follow
                self.skip_whitespace()
                if self.eof() or self.peek() in ',>+~':
                    self.error()
                compound = self.parse_compound_selector()
                parts.append((combinator, compound))
                combinator = None
                continue
            else:
                # start of compound
                if parts:
                    if had_ws:
                        combinator = ' '
                    elif combinator is None:
                        self.error()
                compound = self.parse_compound_selector()
                parts.append((combinator if parts else None, compound))
                combinator = None
                # loop
                # If next char is not whitespace/combinator/comma/eof, parse_compound would have consumed it; continue loop will error
                continue
        if combinator is not None:
            self.error()
        if not parts:
            self.error()
        return parts
    def parse_compound_selector(self):
        compound = []
        # optional type or universal
        c = self.peek()
        if c == '*' or c == '|' or _is_name_start(c) or c == '-' or c == '\\':
            # Could be namespace/type; if next chars indicate start of . # [ : then no type
            save = self.i
            try:
                type_sel = self.try_parse_type_selector()
                if type_sel is not None:
                    compound.append(type_sel)
            except SelectorError:
                self.i = save
                # if it was meant as type, will fail below if no simple selectors
                # But for cases like '-' alone, try_parse handles.
                # reraise if char not in simple starters
                if c not in '.#[:':
                    raise
        while not self.eof():
            c = self.peek()
            if c == '#':
                val = self.parse_hash_id()
                compound.append(('id', val))
            elif c == '.':
                self.i += 1
                val = self.parse_ident()
                compound.append(('class', val))
            elif c == '[':
                compound.append(self.parse_attr_selector())
            elif c == ':':
                compound.append(self.parse_pseudo())
            else:
                break
        if not compound:
            self.error()
        return compound
    def try_parse_type_selector(self):
        # Returns ('type', ns_kind, name) or ('universal', ns_kind) ; ns_kind: None=any(no prefix present? careful)
        # Spec representation:
        #  - no namespace prefix: namespace is None meaning any namespace (for type selectors in kuchiki)
        #  - '*|' -> any, '|': empty ns ('')
        #  - 'ident|' -> error (undefined namespace) unless ident == '*'
        save = self.i
        # Namespace part possibilities
        # First read a component: '*', ident, or empty before '|'
        prefix = None  # None=no prefix syntax, '*'=star, ''=empty, other=name -> error
        name = None
        is_universal = False
        # Check for '|'
        if self.peek() == '|':
            prefix = ''
            self.i += 1
            # name or *
            if self.peek() == '*':
                self.i += 1; return ('universal', prefix)
            else:
                name = self.parse_ident()
                return ('type', prefix, name)
        # Read first component ident or *
        if self.peek() == '*':
            self.i += 1
            is_universal = True
            first = '*'
        elif self.peek() == '\\' or _is_name_start(self.peek()) or self.peek() == '-':
            first = self.parse_ident()
        else:
            return None
        if self.peek() == '|':
            # namespace separator, but need ensure not '||' column combinator (not supported)
            if self.peek(1) == '|':
                self.error()
            self.i += 1
            prefix = first  # '*' or named
            if prefix != '*':
                # named namespace undefined
                self.error()
            if self.peek() == '*':
                self.i += 1; return ('universal', prefix)
            else:
                name = self.parse_ident()
                return ('type', prefix, name)
        else:
            if is_universal:
                return ('universal', None)
            else:
                return ('type', None, first)
    def parse_attr_selector(self):
        # At '['
        self.i += 1
        self.skip_whitespace()
        # Attribute name with possible namespace
        ns = ''  # '' = empty ns (default for attr), other: '*' for any, named -> error
        # Check namespace syntax
        save = self.i
        # Cases: '|name', '*|name', 'name|name'
        if self.peek() == '|':
            self.i += 1
            ns = ''
            attr_name = self.parse_ident()
        elif self.peek() == '*':
            # could be *|name or just an error (attribute name can't be *)
            if self.peek(1) == '|':
                self.i += 2
                ns = '*'
                attr_name = self.parse_ident()
            else:
                self.error()
        else:
            first = self.parse_ident()
            if self.peek() == '|':
                if self.peek(1) == '=':
                    # it's actually the operator |= , not a namespace separator. So attr name is first, operator handled below.
                    attr_name = first
                    ns = ''
                else:
                    # named namespace prefix -> error (undefined namespace)
                    self.error()
            else:
                attr_name = first
        self.skip_whitespace()
        if self.eof():
            # EOF closes attribute selector (observed: [data-x matches)
            return ('attr_exists', ns, attr_name)
        if self.peek() == ']':
            self.i += 1
            return ('attr_exists', ns, attr_name)
        # operator
        op = None
        if self.peek() in '~|^$*':
            # need check it's followed by '='
            oc = self.peek()
            self.i += 1
            if self.peek() != '=':
                self.error()
            self.i += 1
            op = oc + '='
        elif self.peek() == '=':
            self.i += 1
            op = '='
        else:
            self.error()
        self.skip_whitespace()
        # Value: string or ident
        if self.eof():
            self.error()
        if self.peek() in ('"', "'"):
            value = self.parse_string()
        else:
            value = self.parse_ident()
        self.skip_whitespace()
        sensitivity = 'sensitive'  # or 'insensitive', or 's' (= sensitive in newer syntax? ascii case-sensitive keyword 's')
        if not self.eof() and self.peek() != ']':
            # modifier ident
            mod = self.parse_ident()
