        assert self.peek() == '#'
        self.i += 1
        # Need to check identifier validity of following sequence.
        # Save position; try parse_ident-like validation but hash may start with digit -> invalid for ID selector.
        # If following is ident start sequence, parse it.
        # Approach: try to determine if the sequence starting here forms an ident.
        # CSS Syntax: hash is an ID if it follows identifier rules.
        # We'll attempt: peek ident parsing on a substring.
        save = self.i
        try:
            val = self.parse_ident()
            return val
        except SelectorError:
            self.error()
    # -------- selector parsing --------
    def parse_selector_list(self):
        selectors = []
        self.skip_whitespace()
        if self.eof():
            self.error()
        while True:
            sel = self.parse_complex_selector()
            selectors.append(sel)
            self.skip_whitespace()
            if self.eof():
                break
            if self.peek() == ',':
                self.i += 1
                self.skip_whitespace()
                if self.eof():
                    self.error()
                continue
            else:
                self.error()
        return selectors
    def parse_complex_selector(self):
        # returns list of (combinator_to_left, compound) ; first combinator None
        parts = []
        combinator = None
        while True:
            had_ws = self.skip_whitespace()
            if self.eof() or self.peek() == ',':
                if not parts:
                    self.error()
                break
            c = self.peek()
            if c in '>+~':
                if not parts:
                    self.error()
                combinator = c
                self.i += 1
                # after combinator, a compound must follow
                self.skip_whitespace()
                if self.eof() or self.peek() in ',>+~':
                    self.error()
                compound = self.parse_compound_selector()
                parts.append((combinator, compound))
                combinator = None
                continue
            else:
                # start of compound
                if parts:
                    if had_ws:
                        combinator = ' '
                    elif combinator is None:
                        self.error()
                compound = self.parse_compound_selector()
                parts.append((combinator if parts else None, compound))
                combinator = None
                # loop
                # If next char is not whitespace/combinator/comma/eof, parse_compound would have consumed it; continue loop will error
                continue
        if combinator is not None:
            self.error()
        if not parts:
            self.error()
        return parts
    def parse_compound_selector(self):
        compound = []
        # optional type or universal
        c = self.peek()
        if c == '*' or c == '|' or _is_name_start(c) or c == '-' or c == '\\':
            # Could be namespace/type; if next chars indicate start of . # [ : then no type
            save = self.i
            try:
                type_sel = self.try_parse_type_selector()
                if type_sel is not None:
                    compound.append(type_sel)
            except SelectorError:
                self.i = save
                # if it was meant as type, will fail below if no simple selectors
                # But for cases like '-' alone, try_parse handles.
                # reraise if char not in simple starters
                if c not in '.#[:':
                    raise
        while not self.eof():
            c = self.peek()
            if c == '#':
                val = self.parse_hash_id()
                compound.append(('id', val))
            elif c == '.':
                self.i += 1
                val = self.parse_ident()
                compound.append(('class', val))
            elif c == '[':
                compound.append(self.parse_attr_selector())
            elif c == ':':
                compound.append(self.parse_pseudo())
            else:
                break
        if not compound:
            self.error()
        return compound
    def try_parse_type_selector(self):
        # Returns ('type', ns_kind, name) or ('universal', ns_kind) ; ns_kind: None=any(no prefix present? careful)
        # Spec representation:
        #  - no namespace prefix: namespace is None meaning any namespace (for type selectors in kuchiki)
        #  - '*|' -> any, '|': empty ns ('')
        #  - 'ident|' -> error (undefined namespace) unless ident == '*'
        save = self.i
        # Namespace part possibilities
        # First read a component: '*', ident, or empty before '|'
        prefix = None  # None=no prefix syntax, '*'=star, ''=empty, other=name -> error
        name = None
        is_universal = False
        # Check for '|'
        if self.peek() == '|':
            prefix = ''
            self.i += 1
            # name or *
            if self.peek() == '*':
                self.i += 1; return ('universal', prefix)
            else:
                name = self.parse_ident()
                return ('type', prefix, name)
        # Read first component ident or *
        if self.peek() == '*':
            self.i += 1
            is_universal = True
            first = '*'
        elif self.peek() == '\\' or _is_name_start(self.peek()) or self.peek() == '-':
            first = self.parse_ident()
        else:
            return None
        if self.peek() == '|':
            # namespace separator, but need ensure not '||' column combinator (not supported)
            if self.peek(1) == '|':
                self.error()
            self.i += 1
            prefix = first  # '*' or named
            if prefix != '*':
                # named namespace undefined
                self.error()
            if self.peek() == '*':
                self.i += 1; return ('universal', prefix)
            else:
                name = self.parse_ident()
                return ('type', prefix, name)
        else:
            if is_universal:
                return ('universal', None)
            else:
                return ('type', None, first)
    def parse_attr_selector(self):
        # At '['
        self.i += 1
        self.skip_whitespace()
        # Attribute name with possible namespace
        ns = ''  # '' = empty ns (default for attr), other: '*' for any, named -> error
        # Check namespace syntax
        save = self.i
        # Cases: '|name', '*|name', 'name|name'
        if self.peek() == '|':
            self.i += 1
            ns = ''
            attr_name = self.parse_ident()
        elif self.peek() == '*':
            # could be *|name or just an error (attribute name can't be *)
            if self.peek(1) == '|':
                self.i += 2
                ns = '*'
                attr_name = self.parse_ident()
            else:
                self.error()
        else:
            first = self.parse_ident()
            if self.peek() == '|':
                if self.peek(1) == '=':
                    # it's actually the operator |= , not a namespace separator. So attr name is first, operator handled below.
                    attr_name = first
                    ns = ''
                else:
                    # named namespace prefix -> error (undefined namespace)
                    self.error()
            else:
                attr_name = first
        self.skip_whitespace()
        if self.eof():
            # EOF closes attribute selector (observed: [data-x matches)
            return ('attr_exists', ns, attr_name)
        if self.peek() == ']':
            self.i += 1
            return ('attr_exists', ns, attr_name)
        # operator
        op = None
        if self.peek() in '~|^$*':
            # need check it's followed by '='
            oc = self.peek()
            self.i += 1
            if self.peek() != '=':
                self.error()
            self.i += 1
            op = oc + '='
        elif self.peek() == '=':
            self.i += 1
            op = '='
        else:
            self.error()
        self.skip_whitespace()
        # Value: string or ident
        if self.eof():
            self.error()
        if self.peek() in ('"', "'"):
            value = self.parse_string()
        else:
            value = self.parse_ident()
        self.skip_whitespace()
        sensitivity = 'sensitive'  # or 'insensitive', or 's' (= sensitive in newer syntax? ascii case-sensitive keyword 's')
        if not self.eof() and self.peek() != ']':
            # modifier ident
            mod = self.parse_ident()
            if mod == 'i' or mod == 'I':
                sensitivity = 'insensitive'
            elif mod == 's' or mod == 'S':
                sensitivity = 'sensitive_explicit'
            else:
                self.error()
            self.skip_whitespace()
        if self.eof():
            # EOF tolerated as close
            return ('attr', ns, attr_name, op, value, sensitivity)
        if self.peek() != ']':
            self.error()
        self.i += 1
        return ('attr', ns, attr_name, op, value, sensitivity)
    def parse_pseudo(self):
        # At ':'
        self.i += 1
        is_element = False
        if self.peek() == ':':
            # pseudo-element always invalid for this implementation
            self.error()
        name = self.parse_ident()
        lname = name  # pseudo names are ASCII case-insensitive; selectors crate requires lowercase? It matches case-insensitively? cssparser lowercases? We'll store as-is and compare lower.
        # functional?
        if not self.eof() and self.peek() == '(':
            self.i += 1
            if lname.lower() in ('nth-child','nth-last-child','nth-of-type','nth-last-of-type'):
                # parse An+B up to ')'
                # collect content until matching ')'
                start = self.i
                depth = 1
                while self.i < self.n and depth > 0:
                    if self.s[self.i] == '(':
                        depth += 1
                    elif self.s[self.i] == ')':
                        depth -= 1
                        if depth == 0:
                            break
                    self.i += 1
                if depth != 0:
                    self.error()
                content = self.s[start:self.i]
                self.i += 1  # ')'
                a, b = parse_nth(content)
                return ('pseudo_functional_nth', lname.lower(), a, b)
            elif lname.lower() == 'not':
                self.skip_whitespace()
                # single simple selector
                simple = self.parse_simple_selector_for_not()
                self.skip_whitespace()
                if self.eof() or self.peek() != ')':
                    self.error()
                self.i += 1
                return ('pseudo_not', simple)
            else:
                # Unknown functional pseudo -> error
                self.error()
        else:
            # non-functional
            allowed = {'root','scope','empty','first-child','last-child','first-of-type','last-of-type','only-child','only-of-type','link','any-link','visited','hover','active','focus','enabled','disabled','checked','indeterminate'}
            low = lname.lower()
            # selectors crate pseudo names are parsed case-insensitively? CSS pseudo classes are ascii case-insensitive. But Rust cssparser may lowercase only if ... We'll accept any case if low in allowed? Test later.
            # Actually original: :First-Child? We'll test; assume cssparser lowercases ident for pseudo? Hmm parse_ident preserves case, selectors parser matches name against a list of strings expecting lowercase; if input is upper, it may fail. We'll need to verify.
            if low not in allowed:
                self.error()
            # But if the raw name is not exactly lowercase, is it accepted? We'll store low and let it match for now, refine after testing.
            if lname != low:
                # Mark: selectors crate compares lowercased? We'll postpone; to be safe, if mixed case, original might panic.
                # We'll check with experiments later; for now accept.
                pass
            return ('pseudo', low)
    def parse_simple_selector_for_not(self):
        # Parse exactly one simple selector: type/universal, #id, .class, [attr], :pseudo (incl functional nth, but not :not)
        self.skip_whitespace()
        c = self.peek()
        if c == '*':
            # could be type/universal with ns
            return self.parse_compound_selector_single()
        if c == '#':
            val = self.parse_hash_id()
            return ('id', val)
        if c == '.':
            self.i += 1
            val = self.parse_ident()
            return ('class', val)
        if c == '[':
            return self.parse_attr_selector()
        if c == ':':
            # pseudo
            p = self.parse_pseudo()
            if p[0] == 'pseudo_not':
                self.error()
            return p
        # type selector
        t = self.try_parse_type_selector()
        if t is None:
            self.error()
        return t

    def parse_compound_selector_single(self):
        # Used only for '*' inside :not - parse one universal/type
        t = self.try_parse_type_selector()
        if t is None:
            self.error()
        return t

def parse_nth(content):
    # content string without parens; Rust cssparser Nth parser
    s = content.strip(' \t\n\r\f')
    low = s.lower()
    if low == 'odd':
        return (2, 1)
    if low == 'even':
        return (2, 0)
    # Use parser logic similar to cssparser: parse An+B microsyntax
    # Remove? cssparser tokenizes content; spaces allowed around signs between n and b etc but not between - and digit for integers.
    # We'll implement token-based:
    # Replace: The string is parsed by rust-cssparser's `parse_nth` which uses ParserInput.
    # Approximate with regex after removing certain spaces.
    # Cases that must fail: '- 3' (space between minus and digit), '1.5', 'n+', '+n-', '2n+1x', 'abc'
    # Implementation steps using a mini parser:
    p = _NthParser(s)
    return p.parse()

class _NthParser:
    def __init__(self, s):
        self.s = s; self.i = 0; self.n = len(s)
    def error(self):
        raise SelectorError("nth")
    def skip_ws(self):
        while self.i < self.n and self.s[self.i] in ' \t\n\r\f':
            self.i += 1
    def parse(self):
        self.skip_ws()
        # Determine
        # Could be signed integer
        # Or [sign] [A] n [sign B] etc, or odd/even already handled
        # We parse as per cssparser nth.rs logic:
        # First see if starts with 'n', '-n', '+n', dimension, number
        s = self.s; i = self.i
        if i >= self.n:
            self.error()
        # Try integer only path: if remainder after parsing an integer is eof (after ws)
        save = self.i
        try:
            val = self.parse_integer()
            self.skip_ws()
            if self.i == self.n:
                return (0, val)
            else:
                self.i = save
                raise SelectorError("not just int")
        except SelectorError:
            self.i = save
        # Now An+B
        # Sign for A
        a_sign = 1
        if self.i < self.n and self.s[self.i] in '+-':
            if self.s[self.i] == '-':
                a_sign = -1
            self.i += 1
            # cssparser: after sign for the n dimension, spaces? For "- n"? It allows? Spec: -n has no space between sign and n? Tokenizer would make "-n" an ident. If input is "- n", that might be ??? Original: ':nth-child(- 3)' panicked (integer). For '- n', likely also fail. If there's whitespace, fail.
            if self.i < self.n and self.s[self.i] in ' \t\n\r\f':
                self.error()
        # A value digits (optional)
        a_val_str = ''
        while self.i < self.n and self.s[self.i].isdigit():
            a_val_str += self.s[self.i]; self.i += 1
        # next char must be n/N
        if self.i >= self.n or self.s[self.i] not in 'nN':
            self.error()
        self.i += 1  # n
        if a_val_str == '':
            a = a_sign * 1
        else:
            a = a_sign * int(a_val_str)
        # After n, there may be '-something' which could be part of ident like 'n-foo'? cssparser checks: if next char is '-' etc, it proceeds to B parsing; but if it's a name char other than ??? '2n+1x' fails later.
        # Optional B
        self.skip_ws()
        if self.i >= self.n:
            return (a, 0)
        if self.s[self.i] not in '+-':
            self.error()
        b_sign = 1 if self.s[self.i] == '+' else -1
        self.i += 1
        self.skip_ws()
        # B digits: cssparser requires a number token; spaces between sign and number were stripped by skip_ws above ("n+ 1" is allowed? Tokenization: n dimension, delim +, number. yes)
        # But for "- 3" integer case, we already errored. For "n- 1", allowed?
        if self.i >= self.n or not self.s[self.i].isdigit():
            self.error()
        b_str = ''
        while self.i < self.n and self.s[self.i].isdigit():
            b_str += self.s[self.i]; self.i += 1
        b = b_sign * int(b_str)
        self.skip_ws()
        if self.i != self.n:
            self.error()
        return (a, b)
    def parse_integer(self):
        # CSS integer token: [+-]? digits, with NO space between sign and digits
        i = self.i
        sign = 1
        if i < self.n and self.s[i] in '+-':
            if self.s[i] == '-': sign = -1
            i += 1
            if i >= self.n or not self.s[i].isdigit():
                self.error()
        if i >= self.n or not self.s[i].isdigit():
            self.error()
        j = i
        while j < self.n and self.s[j].isdigit():
            j += 1
        val = sign * int(self.s[i:j])
        self.i = j
        return val

def parse_selector_list(s):
    parser = CSSParser(s)
    return parser.parse_selector_list()

# ---------- matching ----------
def _ascii_lower(s):
    return ''.join(chr(ord(c)+32) if 'A' <= c <= 'Z' else c for c in s)

def _get_id(el):
    v = el.get_attr('id')
    return v
def _get_class_list(el):
    v = el.get_attr('class')
    if v is None:
        return []
    # split on HTML whitespace (space, tab, LF, FF, CR) - document text already has CR normalized to LF except charrefs.
    parts = []
    cur = ''
    for c in v:
        if c in ' \t\n\f\r':
            if cur != '':
                parts.append(cur); cur = ''
        else:
            cur += c
    if cur != '':
        parts.append(cur)
    return parts

def _element_parent(el):
    p = el.parent
    while p is not None and p.kind != 'element':
        # parent should be document or element; for elements whose parent is documentfragment (template content) not in our tree
        if p.kind == 'document':
            return None
        p = p.parent
    return p

def _preceding_element_siblings(el):
    p = el.parent
    if p is None:
        return []
    out = []
    for c in p.children:
        if c is el:
            break
        if c.kind == 'element':
            out.append(c)
    return out
def _following_element_siblings(el):
    p = el.parent
    if p is None:
        return []
    out = []
    seen = False
    for c in p.children:
        if c is el:
            seen = True; continue
        if seen and c.kind == 'element':
            out.append(c)
    return out
def _sibling_elements(el):
    p = el.parent
    if p is None:
        return [el]
    return [c for c in p.children if c.kind == 'element']

def _is_html_el(el):
    return el.ns == HTML_NS

def _match_type(el, ns, name):
    # ns: None => any namespace, '*' => any, '' => empty ns
    if ns is not None and ns != '*':
        # ns == '' means no namespace
        if el.ns != '':
            return False
    # name compare: HTML elements in HTML doc are case-insensitive
    if _is_html_el(el):
        return _ascii_lower(el.local) == _ascii_lower(name)
    else:
        return el.local == name

def _match_attr_value(actual, op, expected, sensitivity):
    if sensitivity == 'insensitive':
        a = _ascii_lower(actual); e = _ascii_lower(expected)
    else:
        a = actual; e = expected
    if op == '=':
        return a == e
    if op == '~=':
        if e == '' or any(c in ' \t\n\f\r' for c in e):
            return False
        parts = []
        cur=''
        for ch in a:
            if ch in ' \t\n\f\r':
                if cur: parts.append(cur); cur=''
            else: cur+=ch
        if cur: parts.append(cur)
        return e in parts
    if op == '|=':
        return a == e or a.startswith(e + '-')
    if op == '^=':
        return e != '' and a.startswith(e)
    if op == '$=':
        return e != '' and a.endswith(e)
    if op == '*=':
        return e != '' and e in a
    return False

def _find_attr_for_selector(el, ns, name):
    # ns: '' empty, '*' any
    found = []
    for a in el.attrs:
        if ns == '*':
            if a.local == name:
                found.append(a)
        elif ns == '':
            if a.ns == '' and a.local == name:
                found.append(a)
        else:
            # shouldn't happen
            pass
    return found

def _match_simple(el, simple, scope_el):
    kind = simple[0]
    if kind == 'universal':
        ns = simple[1]
        if ns is not None and ns != '*':
            if el.ns != '':
                return False
        return True
    if kind == 'type':
        _, ns, name = simple
        return _match_type(el, ns, name)
    if kind == 'id':
        v = _get_id(el)
        return v is not None and v == simple[1]
    if kind == 'class':
        return simple[1] in _get_class_list(el)
    if kind == 'attr_exists':
        _, ns, name = simple
        # Attribute name matching: For HTML elements, attribute local name is ... selectors crate: attribute names for HTML elements are case-insensitive.
        # Kuchiki element attr_exists lowercases name if is_html?
        # Original tests: [DATA-X] matched html element with data-x. So we need handle name case:
        # Determine lookup names:
        if _is_html_el(el):
            # selectors crate lowercases attribute name in parser for html? The parser stores name as given but matching lowercases for html element.
            # Our find function needs case-insensitive local for html ns=='' attrs.
            # We'll handle specially:
            for a in el.attrs:
                if ns == '*':
                    if _ascii_lower(a.local) == _ascii_lower(name):
                        return True
                elif ns == '':
                    if a.ns == '' and _ascii_lower(a.local) == _ascii_lower(name):
                        return True
            return False
        else:
            return len(_find_attr_for_selector(el, ns, name)) > 0
    if kind == 'attr':
        _, ns, name, op, value, sensitivity = simple
        if _is_html_el(el):
            candidates = []
            for a in el.attrs:
                if ns == '*':
                    if _ascii_lower(a.local) == _ascii_lower(name):
                        candidates.append(a)
                elif ns == '':
                    if a.ns == '' and _ascii_lower(a.local) == _ascii_lower(name):
                        candidates.append(a)
            return any(_match_attr_value(a.value, op, value, sensitivity) for a in candidates)
        else:
            candidates = _find_attr_for_selector(el, ns, name)
            return any(_match_attr_value(a.value, op, value, sensitivity) for a in candidates)
    if kind == 'pseudo':
        name = simple[1]
        return _match_pseudo_nonfunctional(el, name, scope_el)
    if kind == 'pseudo_functional_nth':
        _, name, a, b = simple
        return _match_nth(el, name, a, b)
    if kind == 'pseudo_not':
        inner = simple[1]
        return not _match_simple(el, inner, scope_el)
    return False

def _match_pseudo_nonfunctional(el, name, scope_el):
    if name == 'root':
        # parent is document
        return el.parent is not None and el.parent.kind == 'document'
    if name == 'scope':
        return scope_el is not None and el is scope_el
    if name == 'empty':
        for c in el.children:
            if c.kind == 'element':
                return False
            if c.kind == 'text':
                return False
            # comments, doctype etc don't count
        return True
    if name == 'first-child':
        return len(_preceding_element_siblings(el)) == 0
    if name == 'last-child':
        return len(_following_element_siblings(el)) == 0
    if name == 'only-child':
        return len(_preceding_element_siblings(el)) == 0 and len(_following_element_siblings(el)) == 0
    if name in ('first-of-type','last-of-type','only-of-type'):
        sibs = _sibling_elements(el)
        same = [s for s in sibs if s.ns == el.ns and s.local == el.local]
        # Note: for HTML elements, local stored lowercase anyway; for foreign, exact.
        if name == 'first-of-type':
            return same and same[0] is el
        if name == 'last-of-type':
            return same and same[-1] is el
        if name == 'only-of-type':
            return len(same) == 1
    if name in ('link','any-link'):
        if el.ns == HTML_NS and el.local in ('a','area','link'):
            return el.has_attr_ns('', 'href')
        return False
    if name in ('visited','hover','active','focus','enabled','disabled','checked','indeterminate'):
        return False
    return False

def _match_nth(el, name, a, b):
    # Determine index (1-based)
    if name in ('nth-child','nth-last-child'):
        sibs = _sibling_elements(el)
        try:
            pos = sibs.index(el)
        except ValueError:
            return False
        if name == 'nth-child':
            idx = pos + 1
        else:
            idx = len(sibs) - pos
    elif name in ('nth-of-type','nth-last-of-type'):
        sibs = _sibling_elements(el)
        same = [s for s in sibs if s.ns == el.ns and s.local == el.local]
        try:
            pos = same.index(el)
        except ValueError:
            return False
