        return node.local in ('mi','mo','mn','ms','mtext','annotation-xml')
    if node.ns == SVG_NS:
        return node.local in ('foreignObject','desc','title')
    return False

class TreeBuilder:
    def __init__(self, tokenizer):
        self.tok = tokenizer
        self.doc = Node('document')
        self.stack = []
        self.mode = 'initial'
        self.original_mode = None
        self.template_modes = []
        self.active_formatting = []  # list of Node or None marker
        self.form_pointer = None
        self.head_pointer = None
        self.frameset_ok = True
        self.foster_parenting = False
        self.ignore_lf = False
        self.pending_table_text = []
        self.pending_table_text_whitespace = True
        self.template_skip_depth = 0
        self.quirks = False
    # ---------- helpers ----------
    def current(self):
        return self.stack[-1] if self.stack else None
    def adjusted_current(self):
        return self.stack[-1] if self.stack else None
    def insert_node_at(self, parent, before, node):
        if before is not None:
            parent.insert_before(node, before)
        else:
            parent.append_child(node)
        return node
    def appropriate_place(self):
        cur = self.current()
        target = cur
        if self.foster_parenting and target is not None and target.ns == HTML_NS and target.local in ('table','tbody','tfoot','thead','tr'):
            # foster parenting
            last_table = None
            for el in reversed(self.stack):
                if el.ns == HTML_NS and el.local == 'table':
                    last_table = el; break
            if last_table is not None:
                if last_table.parent is not None:
                    return (last_table.parent, last_table)
                else:
                    # element before table in stack
                    idx = self.stack.index(last_table)
                    prev = self.stack[idx-1] if idx > 0 else self.doc
                    return (prev, None)
        return (target if target is not None else self.doc, None)
    def insert_element(self, node):
        parent, before = self.appropriate_place()
        self.insert_node_at(parent, before, node)
        return node
    def insert_character(self, data):
        if data == '':
            return
        parent, before = self.appropriate_place()
        # Character insertion: if before is not None, inserted text node before it; merging with preceding text sibling.
        if before is not None:
            idx = parent.children.index(before)
            if idx > 0 and parent.children[idx-1].kind == 'text':
                parent.children[idx-1].data += data
                return
            tn = Node('text', data=data)
            parent.insert_before(tn, before)
            return
        if parent.children and parent.children[-1].kind == 'text':
            parent.children[-1].data += data
        else:
            parent.append_child(Node('text', data=data))
    def insert_comment(self, data, parent=None, before=None):
        if parent is None:
            parent, before = self.appropriate_place()
        cn = Node('comment', data=data)
        self.insert_node_at(parent, before, cn)
        return cn
    def create_element(self, tag_name, attrs, ns):
        # Returns element with proper local and adjusted attrs.
        local = tag_name
        prefix = None
        if ns == SVG_NS:
            local = SVG_ELEMENT_ADJUST.get(tag_name, tag_name)
        el = Node('element', ns=ns, local=local, prefix=prefix)
        for aname, avalue in attrs:
            if ns == SVG_NS:
                adj_name = SVG_ATTR_ADJUST.get(aname, aname)
            elif ns == MATHML_NS:
                adj_name = 'definitionURL' if aname == 'definitionurl' else aname
            else:
                adj_name = aname
            if (ns == SVG_NS or ns == MATHML_NS) and adj_name in FOREIGN_ATTR_ADJUST:
                # But foreign attr adjustment applies by original name (lowercased) - use original aname as key
                fns, fprefix, flocal = FOREIGN_ATTR_ADJUST[aname] if aname in FOREIGN_ATTR_ADJUST else FOREIGN_ATTR_ADJUST[adj_name]
                el.attrs.append(Attr(fns, flocal, fprefix, avalue))
            elif (ns == SVG_NS or ns == MATHML_NS) and aname in FOREIGN_ATTR_ADJUST:
                fns, fprefix, flocal = FOREIGN_ATTR_ADJUST[aname]
                el.attrs.append(Attr(fns, flocal, fprefix, avalue))
            else:
                # For foreign elements, attr local is adj_name (with case adjustments)
                el.attrs.append(Attr("", adj_name, None, avalue))
        return el
    def create_html_element(self, token):
        el = Node('element', ns=HTML_NS, local=token.name)
        for aname, avalue in token.attrs:
            el.attrs.append(Attr("", aname, None, avalue))
        return el
    def insert_html_element_for_token(self, token, push=True):
        el = self.create_html_element(token)
        self.insert_element(el)
        if push:
            self.stack.append(el)
        return el
    def insert_foreign_element_for_token(self, token, ns, push=True):
        el = self.create_element(token.name, token.attrs, ns)
        self.insert_element(el)
        if push:
            self.stack.append(el)
        return el
    def is_in_scope(self, names, scope_type='default', specific_ns=None):
        # names: set of local names or a single string; check from top.
        if isinstance(names, str):
            names = {names}
        boundaries_default = {'applet','caption','html','table','td','th','marquee','object','template'}
        for el in reversed(self.stack):
            if el.kind != 'element':
                continue
            if el.local in names and (scope_type not in ('table',) or True):
                # For table scope, need also consider ns? HTML names
                return True
            # boundary check
            is_boundary = False
            if scope_type == 'default':
                if el.ns == HTML_NS and el.local in boundaries_default: is_boundary = True
                elif el.ns == MATHML_NS and el.local in ('mi','mo','mn','ms','mtext','annotation-xml'): is_boundary = True
                elif el.ns == SVG_NS and el.local in ('foreignObject','desc','title'): is_boundary = True
            elif scope_type == 'list_item':
                if el.ns == HTML_NS and el.local in boundaries_default.union({'ol','ul'}): is_boundary = True
                elif el.ns == MATHML_NS and el.local in ('mi','mo','mn','ms','mtext','annotation-xml'): is_boundary = True
                elif el.ns == SVG_NS and el.local in ('foreignObject','desc','title'): is_boundary = True
            elif scope_type == 'button':
                if el.ns == HTML_NS and el.local in boundaries_default.union({'button'}): is_boundary = True
                elif el.ns == MATHML_NS and el.local in ('mi','mo','mn','ms','mtext','annotation-xml'): is_boundary = True
                elif el.ns == SVG_NS and el.local in ('foreignObject','desc','title'): is_boundary = True
            elif scope_type == 'table':
                if el.ns == HTML_NS and el.local in ('html','table','template'): is_boundary = True
            elif scope_type == 'select':
                # element is in select scope if it's not descendant of optgroup/option? Simplification: boundaries are all except optgroup/option
                if not (el.ns == HTML_NS and el.local in ('optgroup','option')):
                    is_boundary = True
                    # But we already checked target before boundary; for select scope, any non-optgroup/option element stops.
                    # However if target is this element we'd have returned.
                    # This matches spec: walk until target or any element not in optgroup/option
                    return False
            if is_boundary:
                return False
        return False
    def has_specific_element_in_scope(self, target_node, scope_type='default'):
        # for adoption etc: check if node in stack
        return target_node in self.stack
    def generate_implied_end_tags(self, exclude=None):
        while self.stack:
            cur = self.current()
            if cur.ns == HTML_NS and cur.local in ('dd','dt','li','optgroup','option','p','rb','rp','rt','rtc') and cur.local != exclude:
                self.stack.pop()
                continue
            break
    def generate_all_implied_end_tags_thoroughly(self):
        while self.stack:
            cur = self.current()
            if cur.ns == HTML_NS and cur.local in ('caption','colgroup','dd','dt','li','optgroup','option','p','rb','rp','rt','rtc','tbody','td','tfoot','th','thead','tr'):
                self.stack.pop()
                continue
            break
    def pop_until_name(self, name):
        while self.stack:
            el = self.stack.pop()
            if el.local == name and el.ns == HTML_NS:
                break
    def pop_until_any(self, names):
        while self.stack:
            el = self.stack.pop()
            if el.local in names:
                break
    def clear_stack_to_context(self, names):
        # pop until current is one of names (HTML)
        while self.stack:
            cur = self.current()
            if cur.ns == HTML_NS and cur.local in names:
                break
            self.stack.pop()
    def close_p_in_button_scope(self):
        if self.is_in_scope('p', 'button'):
            self.generate_implied_end_tags(exclude='p')
            self.pop_until_name('p')
    # -- active formatting --
    def clear_active_formatting_to_marker(self):
        while self.active_formatting:
            e = self.active_formatting.pop()
            if e is None:
                break
    def push_active_formatting(self, el):
        # Noah's Ark clause (3 identical)
        count = 0
        earliest = None
        for e in reversed(self.active_formatting):
            if e is None:
                break
            if e.local == el.local and e.ns == el.ns and len(e.attrs) == len(el.attrs) and all(any(a.ns==b.ns and a.local==b.local and a.value==b.value for b in el.attrs) for a in e.attrs):
                count += 1
                earliest = e
        if count == 3 and earliest is not None:
            try:
                self.active_formatting.remove(earliest)
            except ValueError:
                pass
        self.active_formatting.append(el)
    def reconstruct_active_formatting(self):
        if not self.active_formatting:
            return
        last = self.active_formatting[-1]
        if last is None or last in self.stack:
            return
        # find first entry to reconstruct
        i = len(self.active_formatting)-1
        while i > 0:
            prev = self.active_formatting[i-1]
            if prev is None or prev in self.stack:
                break
            i -= 1
        while i < len(self.active_formatting):
            entry = self.active_formatting[i]
            # clone element
            clone = Node('element', ns=entry.ns, local=entry.local, prefix=entry.prefix)
            clone.attrs = [Attr(a.ns, a.local, a.prefix, a.value) for a in entry.attrs]
            self.insert_element(clone)
            self.stack.append(clone)
            self.active_formatting[i] = clone
            i += 1
    def insert_marker(self):
        self.active_formatting.append(None)
    # -- raw switching helpers --
    def switch_tokenizer_for_raw(self, tag_name):
        if tag_name in ('title','textarea'):
            self.tok.state = 'rcdata'; self.tok.raw_tag = tag_name
        elif tag_name == 'script':
            self.tok.state = 'scriptdata'; self.tok.raw_tag = 'script'
        elif tag_name == 'plaintext':
            self.tok.state = 'plaintext'; self.tok.raw_tag = 'plaintext'
        elif tag_name in ('style','xmp','iframe','noembed','noframes','noscript'):
            self.tok.state = 'rawtext'; self.tok.raw_tag = tag_name
        # else data
    # Such elements that are parsed as raw/RCDATA in HTML content. Caller inserts element then calls this.
