# ---------------- HTML parsing ----------------
from html.entities import html5 as _HTML5_ENTITIES

_C1_REPLACEMENTS = {
0x80:0x20AC,0x82:0x201A,0x83:0x0192,0x84:0x201E,0x85:0x2026,0x86:0x2020,0x87:0x2021,0x88:0x02C6,0x89:0x2030,0x8A:0x0160,0x8B:0x2039,0x8C:0x0152,0x8E:0x017D,0x91:0x2018,0x92:0x2019,0x93:0x201C,0x94:0x201D,0x95:0x2022,0x96:0x2013,0x97:0x2014,0x98:0x02DC,0x99:0x2122,0x9A:0x0161,0x9B:0x203A,0x9C:0x0153,0x9E:0x017E,0x9F:0x0178,
}

class Token:
    __slots__ = ('kind','name','attrs','self_closing','data','doctype_name')
    def __init__(self, kind, name=None, attrs=None, self_closing=False, data=None, doctype_name=None):
        self.kind = kind; self.name=name; self.attrs=attrs or []; self.self_closing=self_closing; self.data=data; self.doctype_name=doctype_name
    def __repr__(self):
        return "Token(%s,%s,%r)" % (self.kind,self.name,self.data)

class Tokenizer:
    def __init__(self, text):
        self.s = text
        self.i = 0
        self.n = len(text)
        self.state = 'data'  # data, rcdata, rawtext, scriptdata, plaintext
        self.raw_tag = None
        self.cdata_allowed = False
    # ---- char refs ----
    def consume_char_ref(self, pos, in_attr):
        # pos at '&', returns (string_to_append, new_pos)
        s = self.s; n = self.n
        if pos + 1 >= n:
            return ("&", pos+1)
        nxt = s[pos+1]
        if nxt == '#':
            j = pos + 2
            is_hex = False
            if j < n and s[j] in 'xX':
                is_hex = True; j += 1
            start_digits = j
            digits_set = '0123456789abcdefABCDEF' if is_hex else '0123456789'
            while j < n and s[j] in digits_set:
                j += 1
            if j == start_digits:
                # no digits: literal; '&' will be output, rest reprocessed normally
                return ("&", pos+1)
            num_str = s[start_digits:j]
            # optional semicolon
            if j < n and s[j] == ';':
                j += 1
            try:
                num = int(num_str, 16 if is_hex else 10)
            except:
                num = 0x110000
            if num == 0 or num > 0x10FFFF or 0xD800 <= num <= 0xDFFF:
                return ("\ufffd", j)
            if num in _C1_REPLACEMENTS:
                num = _C1_REPLACEMENTS[num]
            return (chr(num), j)
        if not (nxt.isalnum()):
            return ("&", pos+1)
        # Named: find longest entity key that is a prefix of input starting at pos+1
        # Keys in _HTML5_ENTITIES include trailing ';' variants and legacy without.
        # We need max length; max key length ~32.
        maxlen = 32
        remaining = s[pos+1:pos+1+maxlen]
        best = None; best_len = 0
        # Entity names consist of alnum and ';' at end possibly
        # Try lengths descending
        for L in range(min(len(remaining), 32), 0, -1):
            cand = remaining[:L]
            if cand in _HTML5_ENTITIES:
                best = cand; best_len = L; break
        if best is None:
            return ("&", pos+1)
        # In attributes: if entity doesn't end with ';' and next char after match is '=' or alphanumeric, don't expand.
        if in_attr and not best.endswith(';'):
            after_idx = pos + 1 + best_len
            if after_idx < n and (s[after_idx] == '=' or s[after_idx].isalnum()):
                return ("&", pos+1)
        return (_HTML5_ENTITIES[best], pos+1+best_len)
    def decode_text_range(self, start, end, in_attr=False):
        # Decode char refs in s[start:end], used for rcdata segment
        out = []
        i = start
        while i < end:
            if self.s[i] == '&':
                txt, ni = self.consume_char_ref(i, in_attr)
                # Ensure we don't consume beyond end in weird case where ref crosses end-tag boundary (shouldn't happen because ref is before '<')
                out.append(txt); i = ni
            else:
                out.append(self.s[i]); i += 1
        return "".join(out)
    # ---- main token ----
    def next_token(self):
        while True:
            if self.state == 'plaintext':
                if self.i >= self.n:
                    return Token('eof')
                data = self.s[self.i:]
                self.i = self.n
                if data:
                    return Token('text', data=data)
                return Token('eof')
            if self.state in ('rcdata','rawtext','scriptdata'):
                tok = self._raw_content_token()
                if tok is not None:
                    return tok
                # state has been switched to data, fall through to parse end tag etc.
                continue
            # data state
            if self.i >= self.n:
                return Token('eof')
            tok = self._data_token()
            if tok is None:
                continue  # skipped tokens like </>
            return tok
    def _find_raw_end(self, start):
        # Find index of appropriate end tag </raw_tag followed by [\t\n\f\r />] or EOF(?), case insensitive, not double escaped for script
        tag = self.raw_tag
        s = self.s; low = s.lower()
        needle = '</' + tag
        pos = start
        if self.state == 'scriptdata':
            return self._find_script_end(start)
        while True:
            idx = low.find(needle, pos)
            if idx == -1:
                return -1
            after = idx + len(needle)
            if after >= self.n or s[after] in '\t\n\f\r />':
                return idx
            pos = idx + 1
    def _find_script_end(self, start):
        s = self.s; low = s.lower()
        pos = start
        escaped = False
        double_escaped = False
        i = start
        while i < self.n:
            if not escaped:
                idx = low.find('</script', i)
                cidx = low.find('<!--', i)
                if cidx != -1 and (idx == -1 or cidx < idx):
                    escaped = True
                    i = cidx + 4
                    continue
                if idx == -1:
                    return -1
                after = idx + len('</script')
                if after >= self.n or s[after] in '\t\n\f\r />':
                    return idx
                i = idx + 1
            else:
                # escaped mode: look for <script and </script
                # find next '<'
                candidates = []
                for needle, kind in [('</script','end'), ('<script','start')]:
                    idx = low.find(needle, i)
                    if idx != -1:
                        # check boundary after tag name
                        after = idx + len(needle)
                        if after < self.n and s[after] not in '\t\n\f\r />':
                            continue
                        candidates.append((idx, kind))
                if not candidates:
                    return -1
                idx, kind = min(candidates)
                if kind == 'start':
                    if not double_escaped:
                        double_escaped = True
                    i = idx + len('<script')
                    continue
                else:  # end
                    if double_escaped:
                        double_escaped = False
                        i = idx + len('</script')
                        continue
                    after = idx + len('</script')
                    if after >= self.n or s[after] in '\t\n\f\r />':
                        return idx
                    i = idx + 1
        return -1
    def _raw_content_token(self):
        tag = self.raw_tag
        start = self.i
        end_idx = self._find_raw_end(start)
        if end_idx == -1:
            # rest is text
            segment = self.s[start:]
            self.i = self.n
            state = self.state
            self.state = 'data'
            if segment == '':
                return None
            if state == 'rcdata':
                segment = self.decode_text_range(start, self.n)
            return Token('text', data=segment)
        if end_idx == start:
            # at end tag, switch to data and let caller parse it
            self.state = 'data'
            return None
        segment_end = end_idx
        if self.state == 'rcdata':
            data = self.decode_text_range(start, segment_end)
        else:
            data = self.s[start:segment_end]
        self.i = end_idx
        # Don't switch state yet; next call will see end tag at start and switch.
        if data == '':
            self.state = 'data'
            return None
        return Token('text', data=data)
    def _data_token(self):
        s = self.s; n = self.n
        i = self.i
        # Text run until a markup start that is a real tag/comment/doctype/end/bogus, or EOF.
        # Process in a loop building text; if we encounter markup, return text first if non-empty, else the markup token.
        text_out = []
        text_start = i
        # We'll scan character by character for '<' and '&'
        pos = i
        while pos < n:
            c = s[pos]
            if c == '&':
                # flush plain text before &
                pass  # decode inline below
                # add text up to pos
                # We'll handle by using an index walk:
                break
            if c == '<':
                break
            pos += 1
        # Simpler walk:
        out = []
        p = i
        while p < n:
            c = s[p]
            if c == '&':
                txt, np = self.consume_char_ref(p, in_attr=False)
                out.append(txt); p = np; continue
            if c == '<':
                # decide if markup
                if p + 1 >= n:
                    out.append('<'); p += 1; break
                nxt = s[p+1]
                if nxt.isalpha() and nxt.isascii():
                    break
                if nxt == '!':
                    break
                if nxt == '/':
                    if p + 2 < n and s[p+2].isalpha() and s[p+2].isascii():
                        break
                    if p + 2 < n and s[p+2] == '>':
                        # skip </> and continue text
                        p += 3
                        continue
                    if p + 2 >= n:
                        out.append('</'); p += 2; break
                    break  # bogus comment
                if nxt == '?':
                    break
                # literal <
                out.append('<'); p += 1; continue
            else:
                # copy a run until < or &
                q = p
                while q < n and s[q] not in '<&':
                    q += 1
                seg = s[p:q]
                # Null handling in data: U+0000 is parse error; spec in body mostly replaces? We saw null stripped in text.
                # We'll replace \x00 with '' here; tokenizer-level for most states, spec data state says ignore? It emits U+FFFD in some modes.
                # Observed: \x00 in text inside div was removed (not FFFD). We'll drop.
                seg = seg.replace('\x00', '')
                out.append(seg); p = q; continue
        if out:
            self.i = p
            return Token('text', data="".join(out))
        # At markup start with empty text
        self.i = p
        return self._markup_token()
    def _markup_token(self):
        s = self.s; n = self.n; i = self.i
        # s[i]=='<'
        if i+1 >= n:
            self.i = n
            return Token('text', data='<')
        nxt = s[i+1]
        if nxt == '!':
            # comment/doctype/cdata/bogus
            if s.startswith('<!--', i):
                return self._comment_token()
            if s[i:i+9].lower() == '<![cdata[':
                if self.cdata_allowed:
                    start = i + 9
                    end = s.find(']]>', start)
                    if end == -1:
                        data = s[start:]; self.i = n
                    else:
                        data = s[start:end]; self.i = end + 3
                    if data == '':
                        return self._data_token() if self.i < n else Token('eof')
                    return Token('text', data=data)
                else:
                    return self._bogus_comment_token(i+2)
            if s[i:i+9].lower() == '<!doctype' and (i+9 >= n or s[i+9] in ' \t\n\f\r>'):
                return self._doctype_token()
            return self._bogus_comment_token(i+2)
        if nxt == '/':
            if i+2 < n and s[i+2] == '>':
                self.i = i+3
                return None
            if i+2 < n and s[i+2].isalpha() and s[i+2].isascii():
                return self._tag_token(is_end=True)
            if i+2 >= n:
                self.i = n
                return Token('text', data='</')
            return self._bogus_comment_token(i+2)
        if nxt == '?':
            return self._bogus_comment_token(i+1)  # data includes '?'
        if nxt.isalpha() and nxt.isascii():
            return self._tag_token(is_end=False)
        # literal <
        self.i = i+1
        return Token('text', data='<')
    def _bogus_comment_token(self, data_start):
        s = self.s; n = self.n
        end = s.find('>', data_start)
        if end == -1:
            data = s[data_start:]; self.i = n
        else:
            data = s[data_start:end]; self.i = end+1
        data = data.replace('\x00', '\ufffd')
        return Token('comment', data=data)
    def _comment_token(self):
        s = self.s; n = self.n; i = self.i
        # starts <!--
        j = i + 4
        if j < n and s[j] == '>':
            self.i = j+1
            return Token('comment', data='')
        if s.startswith('->', j):
            self.i = j+2
            return Token('comment', data='')
        # find closing --> or --!>
        pos = j
        while pos < n:
            idx1 = s.find('-->', pos)
            idx2 = s.find('--!>', pos)
            candidates = []
            if idx1 != -1: candidates.append((idx1, 3))
            if idx2 != -1: candidates.append((idx2, 4))
            if not candidates:
