                    last_table = el; break
            if last_table is not None:
                if last_table.parent is not None:
                    return (last_table.parent, last_table)
                else:
                    # element before table in stack
                    idx = self.stack.index(last_table)
                    prev = self.stack[idx-1] if idx > 0 else self.doc
                    return (prev, None)
