    def consume_char_ref(self, pos, in_attr):
        # pos at '&', returns (string_to_append, new_pos)
        s = self.s; n = self.n
        if pos + 1 >= n:
            return ("&", pos+1)
        nxt = s[pos+1]
        if nxt == '#':
            j = pos + 2
            is_hex = False
            if j < n and s[j] in 'xX':
                is_hex = True; j += 1
