            digits_set = '0123456789abcdefABCDEF' if is_hex else '0123456789'
            while j < n and s[j] in digits_set:
                j += 1
            if j == start_digits:
                # no digits: literal; '&' will be output, rest reprocessed normally
                return ("&", pos+1)
            num_str = s[start_digits:j]
            # optional semicolon
            if j < n and s[j] == ';':
                j += 1
            try:
                num = int(num_str, 16 if is_hex else 10)
            except:
                num = 0x110000
            if num == 0 or num > 0x10FFFF or 0xD800 <= num <= 0xDFFF:
                return ("\ufffd", j)
            if num in _C1_REPLACEMENTS:
                num = _C1_REPLACEMENTS[num]
            return (chr(num), j)
