        # Keys in _HTML5_ENTITIES include trailing ';' variants and legacy without.
        # We need max length; max key length ~32.
        maxlen = 32
        remaining = s[pos+1:pos+1+maxlen]
        best = None; best_len = 0
        # Entity names consist of alnum and ';' at end possibly
        # Try lengths descending
        for L in range(min(len(remaining), 32), 0, -1):
            cand = remaining[:L]
            if cand in _HTML5_ENTITIES:
                best = cand; best_len = L; break
        if best is None:
            return ("&", pos+1)
        # In attributes: if entity doesn't end with ';' and next char after match is '=' or alphanumeric, don't expand.
        if in_attr and not best.endswith(';'):
            after_idx = pos + 1 + best_len
            if after_idx < n and (s[after_idx] == '=' or s[after_idx].isalnum()):
                return ("&", pos+1)
