        i = start
        while i < self.n:
            if not escaped:
                idx = low.find('</script', i)
                cidx = low.find('<!--', i)
                if cidx != -1 and (idx == -1 or cidx < idx):
                    escaped = True
                    i = cidx + 4
                    continue
                if idx == -1:
                    return -1
                after = idx + len('</script')
                if after >= self.n or s[after] in '\t\n\f\r />':
                    return idx
                i = idx + 1
            else:
                # escaped mode: look for <script and </script
                # find next '<'
                candidates = []
                for needle, kind in [('</script','end'), ('<script','start')]:
                    idx = low.find(needle, i)
                    if idx != -1:
                        # check boundary after tag name
                        after = idx + len(needle)
                        if after < self.n and s[after] not in '\t\n\f\r />':
                            continue
                        candidates.append((idx, kind))
                if not candidates:
                    return -1
                idx, kind = min(candidates)
                if kind == 'start':
                    if not double_escaped:
                        double_escaped = True
                    i = idx + len('<script')
                    continue
                else:  # end
                    if double_escaped:
                        double_escaped = False
                        i = idx + len('</script')
                        continue
                    after = idx + len('</script')
                    if after >= self.n or s[after] in '\t\n\f\r />':
                        return idx
                    i = idx + 1
        return -1
    def _raw_content_token(self):
        tag = self.raw_tag
        start = self.i
        end_idx = self._find_raw_end(start)
        if end_idx == -1:
            # rest is text
            segment = self.s[start:]
            self.i = self.n
            state = self.state
            self.state = 'data'
            if segment == '':
                return None
            if state == 'rcdata':
                segment = self.decode_text_range(start, self.n)
            return Token('text', data=segment)
        if end_idx == start:
            # at end tag, switch to data and let caller parse it
            self.state = 'data'
            return None
        segment_end = end_idx
        if self.state == 'rcdata':
            data = self.decode_text_range(start, segment_end)
        else:
            data = self.s[start:segment_end]
        self.i = end_idx
        # Don't switch state yet; next call will see end tag at start and switch.
        if data == '':
            self.state = 'data'
            return None
        return Token('text', data=data)
    def _data_token(self):
        s = self.s; n = self.n
        i = self.i
        # Text run until a markup start that is a real tag/comment/doctype/end/bogus, or EOF.
        # Process in a loop building text; if we encounter markup, return text first if non-empty, else the markup token.
        text_out = []
        text_start = i
        # We'll scan character by character for '<' and '&'
        pos = i
        while pos < n:
            c = s[pos]
            if c == '&':
                # flush plain text before &
                pass  # decode inline below
                # add text up to pos
                # We'll handle by using an index walk:
                break
            if c == '<':
                break
            pos += 1
        # Simpler walk:
        out = []
        p = i
        while p < n:
            c = s[p]
            if c == '&':
                txt, np = self.consume_char_ref(p, in_attr=False)
                out.append(txt); p = np; continue
            if c == '<':
                # decide if markup
                if p + 1 >= n:
                    out.append('<'); p += 1; break
                nxt = s[p+1]
                if nxt.isalpha() and nxt.isascii():
                    break
                if nxt == '!':
                    break
                if nxt == '/':
                    if p + 2 < n and s[p+2].isalpha() and s[p+2].isascii():
                        break
                    if p + 2 < n and s[p+2] == '>':
                        # skip </> and continue text
                        p += 3
                        continue
                    if p + 2 >= n:
                        out.append('</'); p += 2; break
                    break  # bogus comment
                if nxt == '?':
                    break
                # literal <
                out.append('<'); p += 1; continue
            else:
                # copy a run until < or &
                q = p
                while q < n and s[q] not in '<&':
                    q += 1
                seg = s[p:q]
                # Null handling in data: U+0000 is parse error; spec in body mostly replaces? We saw null stripped in text.
                # We'll replace \x00 with '' here; tokenizer-level for most states, spec data state says ignore? It emits U+FFFD in some modes.
                # Observed: \x00 in text inside div was removed (not FFFD). We'll drop.
                seg = seg.replace('\x00', '')
                out.append(seg); p = q; continue
        if out:
            self.i = p
            return Token('text', data="".join(out))
        # At markup start with empty text
        self.i = p
        return self._markup_token()
    def _markup_token(self):
        s = self.s; n = self.n; i = self.i
        # s[i]=='<'
        if i+1 >= n:
            self.i = n
            return Token('text', data='<')
        nxt = s[i+1]
        if nxt == '!':
            # comment/doctype/cdata/bogus
            if s.startswith('<!--', i):
                return self._comment_token()
            if s[i:i+9].lower() == '<![cdata[':
                if self.cdata_allowed:
                    start = i + 9
                    end = s.find(']]>', start)
                    if end == -1:
                        data = s[start:]; self.i = n
                    else:
                        data = s[start:end]; self.i = end + 3
                    if data == '':
                        return self._data_token() if self.i < n else Token('eof')
                    return Token('text', data=data)
                else:
                    return self._bogus_comment_token(i+2)
            if s[i:i+9].lower() == '<!doctype' and (i+9 >= n or s[i+9] in ' \t\n\f\r>'):
                return self._doctype_token()
            return self._bogus_comment_token(i+2)
        if nxt == '/':
            if i+2 < n and s[i+2] == '>':
                self.i = i+3
                return None
            if i+2 < n and s[i+2].isalpha() and s[i+2].isascii():
                return self._tag_token(is_end=True)
            if i+2 >= n:
                self.i = n
                return Token('text', data='</')
            return self._bogus_comment_token(i+2)
        if nxt == '?':
            return self._bogus_comment_token(i+1)  # data includes '?'
        if nxt.isalpha() and nxt.isascii():
            return self._tag_token(is_end=False)
        # literal <
        self.i = i+1
        return Token('text', data='<')
    def _bogus_comment_token(self, data_start):
        s = self.s; n = self.n
        end = s.find('>', data_start)
        if end == -1:
            data = s[data_start:]; self.i = n
        else:
            data = s[data_start:end]; self.i = end+1
        data = data.replace('\x00', '\ufffd')
        return Token('comment', data=data)
    def _comment_token(self):
        s = self.s; n = self.n; i = self.i
        # starts <!--
        j = i + 4
        if j < n and s[j] == '>':
            self.i = j+1
            return Token('comment', data='')
        if s.startswith('->', j):
            self.i = j+2
            return Token('comment', data='')
        # find closing --> or --!>
        pos = j
        while pos < n:
            idx1 = s.find('-->', pos)
            idx2 = s.find('--!>', pos)
            candidates = []
            if idx1 != -1: candidates.append((idx1, 3))
            if idx2 != -1: candidates.append((idx2, 4))
            if not candidates:
                data = s[j:]; self.i = n
                return Token('comment', data=data.replace('\x00','\ufffd'))
            idx, ln = min(candidates)
            data = s[j:idx]
            self.i = idx + ln
            return Token('comment', data=data.replace('\x00','\ufffd'))
        data = s[j:]; self.i = n
        return Token('comment', data=data)
    def _doctype_token(self):
        s = self.s; n = self.n; i = self.i
        j = i + 9  # <!doctype
        while j < n and s[j] in ' \t\n\f\r': j += 1
        start = j
        while j < n and s[j] not in ' \t\n\f\r>': j += 1
        name = s[start:j].lower()
        # skip to >
        end = s.find('>', j)
        self.i = n if end == -1 else end+1
        return Token('doctype', doctype_name=name if name else None)
    def _tag_token(self, is_end):
        s = self.s; n = self.n
        i = self.i + (2 if is_end else 1)
        start = i
        while i < n and s[i] not in ' \t\n\f\r/>': i += 1
        name = s[start:i].replace('\x00','\ufffd')
        # ASCII lowercase
        name = ''.join(chr(ord(c)+32) if 'A' <= c <= 'Z' else c for c in name)
        attrs = []
        attr_names_seen = set()
        self_closing = False
        # attribute loop
        while True:
            while i < n and s[i] in ' \t\n\f\r': i += 1
            if i >= n:
                self.i = n
                return Token('eof')
            c = s[i]
            if c == '>':
                i += 1
                break
            if c == '/':
                if i+1 < n and s[i+1] == '>':
                    self_closing = True; i += 2; break
                else:
                    i += 1; continue
            # attr name
            astart = i
            if s[i] == '=':
                i += 1  # spec treats leading = as part of name
            while i < n and s[i] not in '= \t\n\f\r/>': i += 1
            aname_raw = s[astart:i]
            aname = ''.join(chr(ord(ch)+32) if 'A' <= ch <= 'Z' else ch for ch in aname_raw).replace('\x00','\ufffd')
            # after name ws
            j = i
            while j < n and s[j] in ' \t\n\f\r': j += 1
            value = ""
            if j < n and s[j] == '=':
                j += 1
                while j < n and s[j] in ' \t\n\f\r': j += 1
                if j >= n:
                    self.i = n; return Token('eof')
                if s[j] in ('"',"'"):
                    quote = s[j]; j += 1
                    vout = []
                    while j < n and s[j] != quote:
                        if s[j] == '&':
                            txt, j2 = self.consume_char_ref(j, in_attr=True)
                            vout.append(txt); j = j2
                        else:
                            ch = s[j]
                            vout.append('\ufffd' if ch == '\x00' else ch); j += 1
                    if j >= n:
                        self.i = n; return Token('eof')
                    j += 1  # quote
                    value = "".join(vout)
                    i = j
                elif s[j] == '>':
                    # missing attr value; treat as "" and leave > for loop
                    value = ""
                    i = j
                else:
                    vout = []
                    while j < n and s[j] not in ' \t\n\f\r>':
                        if s[j] == '&':
                            txt, j2 = self.consume_char_ref(j, in_attr=True)
                            vout.append(txt); j = j2
                        else:
                            ch = s[j]
                            vout.append('\ufffd' if ch == '\x00' else ch); j += 1
                    value = "".join(vout)
                    i = j
            else:
                i = j
                value = ""
            if aname not in attr_names_seen:
                attr_names_seen.add(aname)
                attrs.append((aname, value))
            # loop continues
        self.i = i
        if is_end:
            return Token('end', name=name, attrs=attrs, self_closing=self_closing)
        else:
            return Token('start', name=name, attrs=attrs, self_closing=self_closing)

