                # Actually spec checks formatting element is in scope; approximate by node presence in scope search:
                # If fmt is in stack but element after scope boundary... spec says ignore token.
                # We'll use: if stack index of fmt is before a scope boundary from top, not in scope.
                # Simpler: if not has element subject in scope (we already queried set), return.
                return True
            if fmt is self.current():
                self.stack.pop()
                self.active_formatting.remove(fmt)
                return True
            fmt_stack_idx = self.stack.index(fmt)
            # furthest block: first special element after fmt in stack
            furthest = None; furthest_idx = -1
            for idx in range(fmt_stack_idx+1, len(self.stack)):
                node = self.stack[idx]
                if _is_special_node(node):
                    furthest = node; furthest_idx = idx; break
            if furthest is None:
                # pop up to and including fmt
                while self.stack:
                    el = self.stack.pop()
                    if el is fmt:
                        break
                if fmt in self.active_formatting:
                    self.active_formatting.remove(fmt)
                return True
            common_ancestor = self.stack[fmt_stack_idx-1] if fmt_stack_idx > 0 else None
            bookmark = fmt_idx_in_afe  # place to insert later (as index)
            node_idx = furthest_idx
            node = furthest
            last = furthest
            inner_count = 0
            while inner_count < 3:
                inner_count += 1
                node_idx -= 1
                if node_idx < 0:
                    break
                node = self.stack[node_idx]
                if node is fmt:
                    break
                if node not in self.active_formatting:
                    # remove from stack and continue (node index stays because next iteration moves up)
                    self.stack.pop(node_idx)
                    furthest_idx -= 1
                    continue
                # replace node with clone in stack and AFE
                clone = Node('element', ns=node.ns, local=node.local, prefix=node.prefix)
                clone.attrs = [Attr(a.ns,a.local,a.prefix,a.value) for a in node.attrs]
                afe_idx = self.active_formatting.index(node)
                self.active_formatting[afe_idx] = clone
                self.stack[node_idx] = clone
                node = clone
                node_idx = self.stack.index(node)
                if last is furthest:
                    bookmark = afe_idx + 1  # insertion point after node in AFE (representation as index)
                # move last to node
                if last.parent is not None:
                    last.parent.remove_child(last)
                node.append_child(last)
                last = node
            # move last to common ancestor (foster if table-ish)
            if last.parent is not None:
                last.parent.remove_child(last)
            if common_ancestor is not None and common_ancestor.ns==HTML_NS and common_ancestor.local in ('table','tbody','tfoot','thead','tr'):
                # foster parent last
                self.foster_parenting = True
                # Use appropriate place manually: insert before table
                # Find last table in stack
                last_table = None
                for el in reversed(self.stack):
                    if el.local=='table': last_table=el; break
                self.foster_parenting = False
                if last_table is not None and last_table.parent is not None:
                    last_table.parent.insert_before(last, last_table)
                elif common_ancestor is not None:
                    common_ancestor.append_child(last)
                else:
                    self.doc.append_child(last)
            elif common_ancestor is not None:
                common_ancestor.append_child(last)
            # create clone of formatting element, move furthest's children into it, append to furthest
            clone_fmt = Node('element', ns=fmt.ns, local=fmt.local, prefix=fmt.prefix)
            clone_fmt.attrs = [Attr(a.ns,a.local,a.prefix,a.value) for a in fmt.attrs]
            children = list(furthest.children)
            for ch in children:
                furthest.remove_child(ch)
                clone_fmt.append_child(ch)
            furthest.append_child(clone_fmt)
            # remove fmt from AFE and insert clone_fmt at bookmark position
            if fmt in self.active_formatting:
                self.active_formatting.remove(fmt)
            insert_pos = min(bookmark, len(self.active_formatting))
            self.active_formatting.insert(insert_pos, clone_fmt)
            # remove fmt from stack, insert clone_fmt immediately below furthest block (before it in stack order)
            if fmt in self.stack:
                self.stack.remove(fmt)
            f_idx = self.stack.index(furthest)
            self.stack.insert(f_idx, clone_fmt)
            # continue outer loop
        return True
    def process_token_in_foreign(self, token):
        adj = self.adjusted_current()
        # text
        if token.kind == 'text':
            # foreign text: insert chars; frameset_ok handling for non-ws
            self.insert_character(token.data)
            return None
        if token.kind == 'comment':
            self.insert_comment(token.data); return None
        if token.kind == 'doctype':
            return None
        if token.kind == 'start':
            name = token.name
            # breakout start tags if current is foreign (not integration)
            breakout = name in ('b','big','blockquote','body','br','center','code','dd','div','dl','dt','em','embed','h1','h2','h3','h4','h5','h6','head','hr','i','img','li','listing','menu','meta','nobr','ol','p','pre','ruby','s','small','span','strike','strong','sub','sup','table','tt','u','ul') or (name == 'font' and any(a[0] in ('color','face','size') for a in token.attrs))
            if breakout and not self._is_integration_point(adj):
                # pop until HTML integration point or html element etc, then reprocess in body
                while self.stack:
                    cur = self.current()
                    if cur.ns == HTML_NS or self._is_html_integration_point(cur) or self._is_mathml_text_integration_point(cur):
                        break
                    self.stack.pop()
                return token  # reprocess in in-body (mode is in_body)
            # Determine namespace for new element
            cur = self.adjusted_current()
            ns = cur.ns if cur is not None else HTML_NS
            if cur is not None and self._is_mathml_text_integration_point(cur):
                # tokens other than mglyph/malignmark are processed as in-body
                if name not in ('mglyph','malignmark'):
                    # process as in body but element should be inserted... spec: in-body processing
                    # Temporarily treat current as HTML for in_body dispatch: we can call a helper that inserts in current place
                    return self.mode_in_body(token)
            if cur is not None and self._is_html_integration_point(cur):
                return self.mode_in_body(token)
            # SVG script special
            el = self.insert_foreign_element_for_token(token, ns, push=True)
            if token.self_closing:
                if el in self.stack:
                    self.stack.remove(el)
                # SVG script self-closing handling omitted
            else:
                # SVG script: ??? tokenizer not switched here (HTML spec: svg script content handling via end tag logic; observed content parsed as markup)
                pass
            return None
        if token.kind == 'end':
            name = token.name
            # If current node's local matches name (case sensitive lowered by tokenizer? For foreign, spec compares)
            # Handle script end in svg separately omitted
            # Walk stack from top
            if self.stack and self.current().local.lower() == name.lower():
                # spec: if current is not matching exactly but would be... simplify pop
                # It may need generate... pop until this node
                while self.stack:
                    el = self.stack.pop()
                    if el.local.lower() == name.lower():
                        break
                return None
            # Look up stack
            idx = len(self.stack)-1
            # First node from top that is HTML -> process in body
            # Algorithm: if stack top doesn't match, keep going up until a node whose local is name; if we encounter HTML node before, switch.
            i = idx
            while i >= 0:
                node = self.stack[i]
                if node.ns == HTML_NS:
                    # process as in body end tag
                    return self.mode_in_body(token)
                if node.local.lower() == name.lower():
                    # pop up to and including that node
                    while len(self.stack) > i:
                        self.stack.pop()
                    break
                i -= 1
            return None
        return None
    # ----- table mode helpers -----
    def clear_stack_to_table_context(self, include=('table','template','html')):
        while self.stack:
            cur = self.current()
            if cur.ns==HTML_NS and cur.local in include:
                break
            self.stack.pop()
    def reset_insertion_mode_appropriate(self):
        self.reset_insertion_mode()
    def mode_in_table(self, token):
        if token.kind == 'text':
            adj = self.adjusted_current()
            if adj is not None and adj.local in ('table','tbody','tfoot','thead','tr'):
                # pending table characters logic
                self.pending_table_text.append(token.data)
                # Determine whitespace: if any char not ws, it's mixed
                # At the point when a non-text token arrives in this mode, pending may already have been flushed by our direct handling below.
                # Simpler: handle text in table context right here:
                # If text is all whitespace, insert into table (appropriate place); else foster parenting.
                data = token.data
                if all(c in ' \t\n\f\r' for c in data):
                    self.insert_character(data)
                else:
                    # Foster text: need to insert while preserving ws/non-ws sequence; foster all non-ws but ws around?
                    # Spec: pending texts: if any non-space, foster parent all pending chars (or split). Our token is one chunk.
                    self.foster_parenting = True
                    self.reconstruct_active_formatting()
                    self.insert_character(data)
                    self.foster_parenting = False
                return None
            else:
                # text when current is e.g. inside foster element? reprocess as in body
                return self.mode_in_body(token)
        if token.kind == 'comment':
            self.insert_comment(token.data); return None
        if token.kind == 'doctype':
            return None
        if token.kind == 'start':
            name = token.name
            if name == 'caption':
                self.clear_stack_to_table_context()
                self.insert_marker()
                el = self.insert_html_element_for_token(token)
                self.mode='in_caption'; return None
            if name == 'colgroup':
                self.clear_stack_to_table_context()
                el = self.insert_html_element_for_token(token)
                self.mode='in_column_group'; return None
            if name == 'col':
                self.clear_stack_to_table_context()
                # imply colgroup
                cg = self.insert_html_element_for_token(Token('start',name='colgroup',attrs=[]))
                self.mode='in_column_group'; return token
            if name in ('tbody','tfoot','thead'):
                self.clear_stack_to_table_context()
                el = self.insert_html_element_for_token(token)
                self.mode='in_table_body'; return None
            if name in ('td','th','tr'):
                self.clear_stack_to_table_context()
                tb = self.insert_html_element_for_token(Token('start',name='tbody',attrs=[]))
                self.mode='in_table_body'; return token
            if name == 'table':
                # close previous table
                if not self.is_in_scope('table','table'):
                    return None
                while self.stack:
                    el=self.stack.pop()
                    if el.local=='table': break
                self.reset_insertion_mode()
                return token
            if name in ('style','script','template'):
                # in head handling: template, script/style raw
                if name == 'template':
                    return self.handle_template_start(token)
                self.parse_generic_raw_or_rcdata_element(token); return None
            if name == 'input':
                typ = None
                for an,v in token.attrs:
                    if an=='type': typ=v
                if typ is not None and typ.lower()=='hidden':
                    self.insert_html_element_for_token(token, push=False)
                return None
            if name == 'form':
                if self.form_pointer is not None:
                    return None
                if any(el.local=='template' for el in self.stack):
                    return None
                el = self.insert_html_element_for_token(token)
                self.form_pointer = el
                # spec: form element is immediately popped in table context
                if el in self.stack:
                    self.stack.remove(el)
                return None
            if name in ('frameset',):
                if not self.frameset_ok:
                    return None
                # ignore? in table frameset is ignored if... spec inserts? Actually anything else foster
                pass
            # anything else in table: foster parenting in body
            self.foster_parenting = True
            result = self.mode_in_body(token)
            self.foster_parenting = False
            return result
        if token.kind == 'end':
            name = token.name
            if name in ('body','caption','col','colgroup','frame','head','tbody','td','tfoot','th','thead','tr'):
                return None
            if name == 'table':
                if not self.is_in_scope('table','table'):
                    return None
                while self.stack:
                    el=self.stack.pop()
                    if el.local=='table': break
                self.reset_insertion_mode(); return None
            if name == 'template':
                return self.handle_template_end(token)
            # anything else: foster in body
            self.foster_parenting = True
            result = self.mode_in_body(token)
            self.foster_parenting = False
            return result
        return None
    def mode_in_caption(self, token):
        if token.kind == 'end' and token.name == 'caption':
            if self.is_in_scope('caption','table'):
                self.generate_implied_end_tags()
                self.pop_until_name('caption')
                self.clear_active_formatting_to_marker()
                self.mode='in_table'
            return None
        if token.kind == 'start' and token.name in ('caption','col','colgroup','tbody','td','tfoot','th','thead','tr'):
            if not self.is_in_scope('caption','table'):
                return None
            self.generate_implied_end_tags()
            self.pop_until_name('caption')
            self.clear_active_formatting_to_marker()
            self.mode='in_table'; return token
        if token.kind == 'end' and token.name == 'table':
            if not self.is_in_scope('caption','table'):
                return None
            self.generate_implied_end_tags()
            self.pop_until_name('caption')
            self.clear_active_formatting_to_marker()
            self.mode='in_table'; return token
        if token.kind == 'end' and token.name in ('body','col','colgroup','html','tbody','td','tfoot','th','thead','tr'):
            return None
        # otherwise in body
        return self.mode_in_body(token)
    def mode_in_column_group(self, token):
        if token.kind == 'text':
            data = token.data
            i=0
            while i < len(data) and data[i] in ' \t\n\f\r': i+=1
            if i == len(data):
                self.insert_character(data); return None
            if i>0:
                self.insert_character(data[:i])
                # then act as anything else for rest
                return Token('text', data=data[i:]) if False else self._colgroup_anything_else(Token('text', data=data[i:]))
            return self._colgroup_anything_else(token)
        if token.kind == 'comment':
            self.insert_comment(token.data); return None
        if token.kind == 'doctype': return None
        if token.kind == 'start' and token.name == 'html':
            return self.mode_in_body(token)
        if token.kind == 'start' and token.name == 'col':
            self.insert_html_element_for_token(token, push=False); return None
        if token.kind == 'end' and token.name == 'colgroup':
            if self.current() is not None and self.current().local=='colgroup':
                self.stack.pop(); self.mode='in_table'
            return None
        if token.kind == 'end' and token.name == 'col':
            return None
        if token.kind == 'start' and token.name == 'template':
            return self.handle_template_start(token)
        if token.kind == 'end' and token.name == 'template':
            return self.handle_template_end(token)
        return self._colgroup_anything_else(token)
    def _colgroup_anything_else(self, token):
        # pop colgroup and reprocess
        if self.current() is not None and self.current().local=='colgroup':
            self.stack.pop(); self.mode='in_table'; return token
        return None
    def mode_in_table_body(self, token):
        if token.kind == 'start' and token.name == 'tr':
            self.clear_stack_to_context({'tbody','tfoot','thead','template','html'})
            el=self.insert_html_element_for_token(token); self.mode='in_row'; return None
        if token.kind == 'start' and token.name in ('td','th'):
            # imply tr
            self.clear_stack_to_context({'tbody','tfoot','thead','template','html'})
            tr=self.insert_html_element_for_token(Token('start',name='tr',attrs=[])); self.mode='in_row'; return token
        if token.kind == 'end' and token.name in ('tbody','tfoot','thead'):
            if self.is_in_scope(token.name,'table'):
                self.clear_stack_to_context({'tbody','tfoot','thead','html'})
                self.stack.pop(); self.mode='in_table'
            return None
        if token.kind == 'start' and token.name in ('caption','col','colgroup','tbody','tfoot','thead'):
            if self.is_in_scope({'tbody','thead','tfoot'},'table'):
                self.clear_stack_to_context({'tbody','tfoot','thead','html'})
                self.stack.pop(); self.mode='in_table'; return token
            return None
        if token.kind == 'end' and token.name == 'table':
            if self.is_in_scope({'tbody','thead','tfoot'},'table'):
                self.clear_stack_to_context({'tbody','tfoot','thead','html'})
                self.stack.pop(); self.mode='in_table'; return token
            return None
        if token.kind == 'end' and token.name in ('body','caption','col','colgroup','html','td','th','tr'):
            return None
        # otherwise in table
        return self.mode_in_table(token)
    def mode_in_row(self, token):
        if token.kind == 'start' and token.name in ('td','th'):
            self.clear_stack_to_context({'tr','template','html'})
            el=self.insert_html_element_for_token(token); self.mode='in_cell'; self.insert_marker(); return None
        if token.kind == 'end' and token.name == 'tr':
            if self.is_in_scope('tr','table'):
                self.clear_stack_to_context({'tr','template','html'}); self.stack.pop(); self.mode='in_table_body'
            return None
        if token.kind == 'start' and token.name in ('caption','col','colgroup','tbody','tfoot','thead','tr'):
            if self.is_in_scope('tr','table'):
                self.clear_stack_to_context({'tr','template','html'}); self.stack.pop(); self.mode='in_table_body'; return token
            return None
        if token.kind == 'end' and token.name == 'table':
            if not self.is_in_scope('tr','table'):
                return None
            self.clear_stack_to_context({'tr','template','html'}); self.stack.pop(); self.mode='in_table_body'; return token
        if token.kind == 'end' and token.name in ('tbody','tfoot','thead'):
            if not self.is_in_scope(token.name,'table'):
                return None
            if self.is_in_scope('tr','table'):
                self.clear_stack_to_context({'tr','template','html'}); self.stack.pop(); self.mode='in_table_body'; return token
            return None
        if token.kind == 'end' and token.name in ('body','caption','col','colgroup','html','td','th'):
            return None
        return self.mode_in_table(token)
    def close_cell(self):
        if self.is_in_scope('td','table'):
            self.generate_implied_end_tags(); self.pop_until_name('td'); self.clear_active_formatting_to_marker(); self.mode='in_row'; return
        if self.is_in_scope('th','table'):
            self.generate_implied_end_tags(); self.pop_until_name('th'); self.clear_active_formatting_to_marker(); self.mode='in_row'; return
    def mode_in_cell(self, token):
        if token.kind == 'end' and token.name in ('td','th'):
            if self.is_in_scope(token.name,'table'):
                self.generate_implied_end_tags(); self.pop_until_name(token.name); self.clear_active_formatting_to_marker(); self.mode='in_row'
            return None
        if token.kind == 'start' and token.name in ('caption','col','colgroup','tbody','td','tfoot','th','thead','tr'):
            if self.is_in_scope({'td','th'},'table'):
                self.close_cell(); return token
            return None
        if token.kind == 'end' and token.name == 'table':
            if self.is_in_scope({'td','th'},'table'):
                self.close_cell(); return token
            return None
        if token.kind == 'end' and token.name in ('tbody','tfoot','thead','tr'):
            if self.is_in_scope(token.name,'table'):
                self.close_cell(); return token
            return None
        if token.kind == 'end' and token.name in ('body','caption','col','colgroup','html'):
            return None
        if token.kind == 'start' and token.name == 'select':
            # in cell, select via in body will switch mode
            return self.mode_in_body(token)
        return self.mode_in_body(token)
    def mode_in_select(self, token):
        if token.kind == 'text':
            if '\x00' in token.data:
                token.data = token.data.replace('\x00','')
                if not token.data: return None
            self.insert_character(token.data); return None
        if token.kind == 'comment':
            self.insert_comment(token.data); return None
        if token.kind == 'doctype': return None
        if token.kind == 'start' and token.name == 'html':
            return self.mode_in_body(token)
        if token.kind == 'start' and token.name == 'option':
            cur=self.current()
            if cur is not None and cur.local=='option': self.stack.pop()
            self.insert_html_element_for_token(token); return None
        if token.kind == 'start' and token.name == 'optgroup':
            cur=self.current()
            if cur is not None and cur.local=='option': self.stack.pop()
            cur=self.current()
            if cur is not None and cur.local=='optgroup': self.stack.pop()
            self.insert_html_element_for_token(token); return None
        if token.kind == 'end' and token.name == 'optgroup':
            # find
            # If current is option and next is optgroup, pop option first
            if len(self.stack)>=2 and self.stack[-1].local=='option' and self.stack[-2].local=='optgroup':
                self.stack.pop()
            if self.current() is not None and self.current().local=='optgroup':
                self.stack.pop()
            return None
        if token.kind == 'end' and token.name == 'option':
            if self.current() is not None and self.current().local=='option':
                self.stack.pop()
            return None
        if token.kind == 'end' and token.name == 'select':
            if self.is_in_scope('select','select'):
                # pop up to select
                while self.stack:
                    el=self.stack.pop()
                    if el.local=='select': break
                self.reset_insertion_mode()
            return None
        if token.kind == 'start' and token.name == 'select':
            # act as end select
            return self.mode_in_select(Token('end', name='select'))
        if token.kind == 'start' and token.name in ('input','keygen','textarea'):
            if not self.is_in_scope('select','select'):
                return None
            while self.stack:
                el=self.stack.pop()
                if el.local=='select': break
            self.reset_insertion_mode(); return token
        if token.kind == 'start' and token.name in ('script','template'):
            if token.name=='template':
                return self.handle_template_start(token)
            self.parse_generic_raw_or_rcdata_element(token); return None
        if token.kind == 'end' and token.name == 'template':
            return self.handle_template_end(token)
        if token.kind == 'start' and token.name == 'hr':
            cur=self.current()
            if cur is not None and cur.local=='option': self.stack.pop()
            cur=self.current()
            if cur is not None and cur.local=='optgroup': self.stack.pop()
            self.insert_html_element_for_token(token,push=False); return None
        if token.kind == 'eof':
            return None
        # anything else ignore
        return None
    def mode_in_template(self, token):
        # We use skip-depth handling instead; this mode should be transient.
        # If token reaches here, treat as in_body for simplicity.
        if token.kind == 'eof':
            # pop templates
            return None
        return self.mode_in_body(token)
    def mode_after_body(self, token):
        if token.kind == 'text':
            data=token.data
            if all(c in ' \t\n\f\r' for c in data):
                # process as in body char (inserted into body)
                return self.mode_in_body(token)
            # any non ws -> parse error, go in_body and reprocess
            self.mode='in_body'; return token
        if token.kind == 'comment':
            # append to html element (first in stack)
            html_el = self.stack[0] if self.stack else self.doc
            html_el.append_child(Node('comment', data=token.data)); return None
        if token.kind == 'doctype': return None
        if token.kind == 'start' and token.name == 'html':
            return self.mode_in_body(token)
        self.mode='in_body'; return token
    def mode_in_frameset(self, token):
        if token.kind == 'text':
            data = ''.join(c for c in token.data if c in ' \t\n\f\r')
            if data:
                self.insert_character(data)
            return None
        if token.kind == 'comment':
            self.insert_comment(token.data); return None
        if token.kind == 'doctype': return None
        if token.kind == 'start' and token.name == 'html':
            return self.mode_in_body(token)
        if token.kind == 'start' and token.name == 'frameset':
            self.insert_html_element_for_token(token); return None
        if token.kind == 'end' and token.name == 'frameset':
            if self.current() is not None and self.current().local=='html':
                return None
            if self.current() is not None:
                self.stack.pop()
            if not any(el.local=='frameset' for el in self.stack):
                self.mode='after_frameset'
            return None
        if token.kind == 'start' and token.name == 'frame':
            self.insert_html_element_for_token(token,push=False); return None
        if token.kind == 'start' and token.name == 'noframes':
