def rust_lossy_decode(data: bytes):
    # String::from_utf8_lossy behaviour.
    out = []
    i = 0
    n = len(data)
    while i < n:
        # try valid sequence
        b0 = data[i]
        if b0 < 0x80:
            out.append(chr(b0)); i += 1; continue
        # Determine width
        if 0xC2 <= b0 <= 0xDF:
            width = 2; min_cp = 0x80; cp = b0 & 0x1F
        elif 0xE0 <= b0 <= 0xEF:
            width = 3; min_cp = 0x800; cp = b0 & 0x0F
        elif 0xF0 <= b0 <= 0xF4:
            width = 4; min_cp = 0x10000; cp = b0 & 0x07
        else:
            out.append('\ufffd'); i += 1; continue
        # Check continuations
        valid_prefix = 1
        ok = True
        if i + width > n:
            # Truncated at EOF if remaining bytes are valid continuations: replace remainder with one FFFD (Rust error_len None)
            # Check remaining are continuation bytes
            remaining_ok = True
            for j in range(i+1, n):
                if not (0x80 <= data[j] <= 0xBF):
                    remaining_ok = False; break
            if remaining_ok:
                # But also need check special ranges for E0/ED/F0/F4 second byte.
                if not _second_byte_ok(b0, data[i+1] if i+1 < n else None):
                    out.append('\ufffd'); i += 1; continue
                out.append('\ufffd'); i = n; continue
            else:
                out.append('\ufffd'); i += 1; continue
        # full width bytes present
        if not _second_byte_ok(b0, data[i+1]):
            out.append('\ufffd'); i += 1; continue
        cont_ok = True
        for j in range(i+1, i+width):
            if not (0x80 <= data[j] <= 0xBF):
                cont_ok = False
                valid_prefix = j - i
                break
        if not cont_ok:
            out.append('\ufffd'); i += valid_prefix; continue
        cp_val = cp
        for j in range(i+1, i+width):
            cp_val = (cp_val << 6) | (data[j] & 0x3F)
        if cp_val < min_cp or cp_val > 0x10FFFF or 0xD800 <= cp_val <= 0xDFFF:
            out.append('\ufffd'); i += 1; continue
        out.append(chr(cp_val)); i += width
    return "".join(out)

def _second_byte_ok(b0, b1):
    if b1 is None or not (0x80 <= b1 <= 0xBF):
        return False
    if b0 == 0xE0:
        return 0xA0 <= b1 <= 0xBF
    if b0 == 0xED:
        return 0x80 <= b1 <= 0x9F
    if b0 == 0xF0:
        return 0x90 <= b1 <= 0xBF
    if b0 == 0xF4:
        return 0x80 <= b1 <= 0x8F
    return True

def parse_html_document(data: bytes):
    text = rust_lossy_decode(data)
    if text.startswith('\ufeff'):
        text = text[1:]
    text = text.replace('\r\n', '\n').replace('\r', '\n')
    tok = Tokenizer(text)
    builder = TreeBuilder(tok)
    return builder.parse()

